INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'black', 'Adjective', '/blæk/', 'đen', 'The cat is black.', 'Mèo màu đen.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'white', 'Adjective', '/waɪt/', 'trắng', 'The snow is white.', 'Tuyết màu trắng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'many', 'Adverb', '/ˈmeɪni/', 'nhiều', 'I have many friends.', 'Tôi có nhiều bạn bè.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'few', 'Adverb', '/fuː/', 'ít', 'I have few books.', 'Tôi có ít quyển sách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'some', 'Pronoun', '/sʌm/', 'một số', 'I have some money.', 'Tôi có một số tiền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'all', 'Adverb', '/ɔːl/', 'tất cả', 'I have all my friends.', 'Tôi có tất cả bạn bè.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'first', 'Adverb', '/fɜːrst/', 'đầu tiên', 'I am first in line.', 'Tôi đứng đầu hàng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'second', 'Adverb', '/ˈsɛkənd/', 'thứ hai', 'I am second in line.', 'Tôi đứng thứ hai.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'third', 'Adverb', '/θɜːrd/', 'thứ ba', 'I am third in line.', 'Tôi đứng thứ ba.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'four', 'Noun', '/fɔːr/', 'bốn', 'I have four books.', 'Tôi có bốn quyển sách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 9, 'five', 'Noun', '/faɪv/', 'năm', 'I have five apples.', 'Tôi có năm quả táo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'bus', 'Noun', '/bʌs/', 'xe buýt', 'I take the bus to work every day.', 'Tôi đi xe buýt đến nơi làm việc mỗi ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'car', 'Noun', '/kɑːr/', 'ô tô', 'I''m going to drive my car to the beach.', 'Tôi sẽ lái ô tô đến bãi biển.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'cycle', 'Noun', '/ˈsaɪkəl/', 'xe đạp', 'It''s a nice day to go cycling.', 'Hôm nay là một ngày tuyệt vời để đi xe đạp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'drive', 'Verb', '/draɪv/', 'đi xe', 'Can you drive me to the airport?', 'Bạn có thể lái tôi đến sân bay không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'motorbike', 'Noun', '/ˈmoʊtərbʌɪk/', 'xe máy', 'I love riding my motorbike on the highway.', 'Tôi yêu đi xe máy trên cao tốc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'park', 'Verb', '/pɑːrk/', 'đỗ xe', 'Please park your car over there.', 'Hãy đỗ xe ở đó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'pedestrian', 'Noun', '/ˌpedɪˈstriːən/', 'người đi bộ', 'Be careful of pedestrians when you''re driving.', 'Hãy cẩn thận với người đi bộ khi bạn lái xe.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'ride', 'Verb', '/raɪd/', 'đi xe', 'I love riding my bike through the park.', 'Tôi yêu đi xe đạp qua công viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'road', 'Noun', '/rəʊd/', 'đường', 'The road to the beach is very long.', 'Đường đến bãi biển rất dài.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'stop', 'Verb', '/stoʊp/', 'dừng xe', 'Please stop the car at the red light.', 'Hãy dừng xe tại đèn đỏ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'taxi', 'Noun', '/ˈtæksi/', 'taksi', 'I''m going to take a taxi to the airport.', 'Tôi sẽ đi taxi đến sân bay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'train', 'Noun', '/treɪn/', 'tàu hỏa', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'travel', 'Verb', '/ˈtrævəl/', 'đi lại', 'I love traveling to new countries.', 'Tôi yêu đi du lịch đến các quốc gia mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'turn', 'Verb', '/tɜːrn/', 'lái xe', 'Please turn left at the next intersection.', 'Hãy rẽ trái tại ngã tư tiếp theo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'vehicle', 'Noun', '/ˈviːhɪkəl/', 'phương tiện giao thông', 'The vehicle is very fast.', 'Phương tiện giao thông này rất nhanh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'walk', 'Verb', '/wɔːk/', 'đi bộ', 'I''m going to walk to the park.', 'Tôi sẽ đi bộ đến công viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'wheel', 'Noun', '/wiːl/', 'hệ số', 'The wheel of the car is very big.', 'Hệ số của ô tô rất lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'bike', 'Noun', '/baɪk/', 'xe đạp', 'I love riding my bike through the park.', 'Tôi yêu đi xe đạp qua công viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'highway', 'Noun', '/ˈhaɪweɪ/', 'đường cao tốc', 'The highway to the beach is very long.', 'Đường cao tốc đến bãi biển rất dài.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A1', 10, 'intersection', 'Noun', '/ˌɪntərˈseɪʃən/', 'ngã tư', 'Please turn left at the next intersection.', 'Hãy rẽ trái tại ngã tư tiếp theo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'shop', 'Noun', '/ʃɒp/', 'cửa hàng', 'I''m going to the shop to buy some milk.', 'Tôi đang đi đến cửa hàng để mua sữa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'price', 'Noun', '/praɪs/', 'giá cả', 'The price of the book is too high.', 'Giá sách này quá cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'buy', 'Verb', '/baɪ/', 'mua', 'I''m going to buy a new phone.', 'Tôi đang đi mua một chiếc điện thoại mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'sell', 'Verb', '/sɛl/', 'bán', 'The shop sells fresh fruits.', 'Cửa hàng này bán trái cây tươi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'discount', 'Noun', '/dɪskˈaʊnt/', 'giảm giá', 'There''s a discount on the new shoes.', 'Có giảm giá cho giày mới này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'expensive', 'Adjective', '/ɛksˈpensɪv/', 'đắt tiền', 'This restaurant is quite expensive.', 'Nhà hàng này khá đắt tiền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'cheap', 'Adjective', '/tʃiːp/', 'rẻ tiền', 'This store sells cheap clothes.', 'Cửa hàng này bán quần áo rẻ tiền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'quality', 'Noun', '/ˈkwɒlɪti/', 'chất lượng', 'The quality of this product is very good.', 'Chất lượng sản phẩm này rất tốt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'brand', 'Noun', '/brænd/', 'thương hiệu', 'This is a well-known brand.', 'Đây là một thương hiệu nổi tiếng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'label', 'Noun', '/ˈleɪbəl/', 'nhãn hiệu', 'The label on the bottle says it''s organic.', 'Nhãn trên chai rượu nói rằng nó là hữu cơ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'offer', 'Verb', '/ˈɒfə/', 'cung cấp', 'The store offers a discount on this product.', 'Cửa hàng này cung cấp giảm giá cho sản phẩm này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'pricey', 'Adjective', '/praɪzi/', 'đắt tiền', 'This restaurant is quite pricey.', 'Nhà hàng này khá đắt tiền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'affordable', 'Adjective', '/əˈfɔrdəbəl/', 'có thể mua được', 'This product is very affordable.', 'Sản phẩm này rất có thể mua được.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'value', 'Noun', '/ˈvælju/', 'giá trị', 'The value of this product is very high.', 'Giá trị sản phẩm này rất cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'priceless', 'Adjective', '/ˈpraɪlsəs/', 'không thể mua được', 'This painting is priceless.', 'Bức tranh này không thể mua được.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'budget', 'Noun', '/ˈbʌdʒɪt/', 'ngân sách', 'I need to make a budget for this month.', 'Tôi cần lập ngân sách cho tháng này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'spend', 'Verb', '/spend/', 'chịu chi', 'I''m going to spend my money on a new phone.', 'Tôi đang đi chi tiền mua một chiếc điện thoại mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'save', 'Verb', '/seɪv/', 'lưu giữ', 'I''m going to save my money for a new car.', 'Tôi đang đi lưu giữ tiền cho một chiếc xe mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 1, 'discounted', 'Adjective', '/dɪskˈaʊntɪd/', 'giảm giá', 'This product is discounted for a limited time.', 'Sản phẩm này giảm giá trong thời gian giới hạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'hotel', 'Noun', '/ˈhoʊtəl/', 'khách sạn', 'I''m staying at a hotel in the city center.', 'Tôi đang ở khách sạn ở trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'tourist', 'Noun', '/ˈtʊərɪst/', 'du khách', 'The tourist information office is located near the train station.', 'Cục thông tin du khách nằm gần ga tàu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'attraction', 'Noun', '/əˈtrækʃən/', 'điểm thu hút', 'The city has many historical attractions to visit.', 'Thành phố có nhiều điểm thu hút lịch sử để tham quan.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'map', 'Noun', '/mæp/', 'bản đồ', 'Can you show me the map of the city?', 'Bạn có thể cho tôi xem bản đồ thành phố không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'direction', 'Noun', '/dɪˈrɛkʃən/', 'hướng dẫn', 'The sign gives directions to the nearest hotel.', 'Bảng chỉ dẫn hướng đến khách sạn gần nhất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'restaurant', 'Noun', '/ˈrɛstərɑːnt/', 'nhà hàng', 'The restaurant serves delicious food at reasonable prices.', 'Nhà hàng phục vụ món ăn ngon với giá cả hợp lý.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'menu', 'Noun', '/ˈmeɪnuː/', 'thực đơn', 'Can you show me the menu, please?', 'Bạn có thể cho tôi xem thực đơn không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'price', 'Noun', '/praɪs/', 'giá cả', 'The price of the hotel room is quite high.', 'Giá phòng khách sạn khá cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'room', 'Noun', '/ruːm/', 'phòng', 'The hotel room has a beautiful view of the city.', 'Phòng khách sạn có tầm nhìn tuyệt đẹp về thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'service', 'Noun', '/ˈsɜːrvɪs/', 'dịch vụ', 'The hotel provides excellent service to its guests.', 'Khách sạn cung cấp dịch vụ xuất sắc cho khách hàng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'ticket', 'Noun', '/ˈtɪkɪt/', 'vé', 'Can you buy me a ticket to the museum?', 'Bạn có thể mua vé cho tôi vào bảo tàng không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'tour', 'Noun', '/tɔːr/', 'du lịch', 'I''m going on a tour of Europe next month.', 'Tôi sẽ đi du lịch châu Âu vào tháng sau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'guide', 'Noun', '/ɡaɪd/', 'hướng dẫn viên', 'The guide will take us to all the main attractions.', 'Hướng dẫn viên sẽ đưa chúng tôi đến tất cả các điểm thu hút chính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'accommodation', 'Noun', '/əkəməˈdeɪʃən/', 'khu nghỉ dưỡng', 'The accommodation was very comfortable and clean.', 'Khu nghỉ dưỡng rất thoải mái và sạch sẽ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'information', 'Noun', '/ɪnˌfɔrˈmeɪʃən/', 'thông tin', 'The tourist information office has a lot of information about the city.', 'Cục thông tin du khách có rất nhiều thông tin về thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'sight', 'Noun', '/saɪt/', 'điểm tham quan', 'The sight of the Eiffel Tower was breathtaking.', 'Tầm nhìn của tháp Eiffel thật tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'transport', 'Noun', '/trænzˈpɔːrt/', 'vận chuyển', 'The hotel offers transport to and from the airport.', 'Khách sạn cung cấp vận chuyển đến và từ sân bay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 2, 'accommodate', 'Verb', '/əkəməˈdeɪt/', 'đưa đón', 'The hotel will accommodate you for the night.', 'Khách sạn sẽ đưa đón bạn qua đêm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'doctor', 'Noun', '/ˈdɒktər/', 'bác sĩ', 'I need to see a doctor about my cold.', 'Tôi cần gặp bác sĩ về cơn ho của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'hospital', 'Noun', '/hɒsˈpɪtəl/', 'bệnh viện', 'I''m going to the hospital to visit my friend.', 'Tôi đang đi bệnh viện thăm bạn của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'patient', 'Noun', '/ˈpeɪʃənt/', 'bệnh nhân', 'The patient is recovering well from the surgery.', 'Bệnh nhân đang hồi phục tốt sau phẫu thuật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'treatment', 'Noun', '/trɪˈt.mənt/', 'phương pháp điều trị', 'The doctor prescribed a new treatment for my condition.', 'Bác sĩ đã kê đơn phương pháp điều trị mới cho tình trạng của tôi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'exercise', 'Noun', '/ɛksərˈsaɪz/', 'thực hành thể dục', 'Regular exercise can help you lose weight.', 'Thực hành thể dục đều đặn có thể giúp bạn giảm cân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'healthy', 'Adjective', '/ˈhɛlθi/', 'sức khỏe tốt', 'Eating fruits and vegetables is healthy for you.', 'Ăn trái cây và rau củ có lợi cho sức khỏe của bạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'medication', 'Noun', '/ˌmɛdɪˈkeɪʃən/', 'liệu pháp', 'The doctor prescribed medication for my headache.', 'Bác sĩ đã kê đơn thuốc cho tôi về cơn đau đầu của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'nurse', 'Noun', '/nɜːrs/', 'y tá', 'The nurse is taking care of the patient.', 'Y tá đang chăm sóc bệnh nhân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'pain', 'Noun', '/peɪn/', 'đau', 'I''m feeling a lot of pain after the surgery.', 'Tôi đang cảm thấy đau rất nhiều sau phẫu thuật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'recovery', 'Noun', '/rɪˈkɒvəri/', 'hồi phục', 'The patient is in the recovery stage after the surgery.', 'Bệnh nhân đang ở giai đoạn hồi phục sau phẫu thuật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'rest', 'Verb', '/rɛst/', 'ngủ', 'I need to rest my eyes after reading for so long.', 'Tôi cần ngủ mắt sau khi đọc trong thời gian dài.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'sickness', 'Noun', '/ˈsɪknəs/', 'bệnh', 'I''m feeling sick and need to go to bed.', 'Tôi đang cảm thấy không khỏe và cần đi ngủ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'sleep', 'Verb', '/sliːp/', 'ngủ', 'I''m going to sleep early tonight.', 'Tôi sẽ đi ngủ sớm tonight.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'symptom', 'Noun', '/ˈsɪmptəm/', 'cơ hội', 'The symptom of the disease is a fever.', 'Cơ hội của bệnh là sốt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'temperature', 'Noun', '/tɪmˈpɛrətʃər/', 'nhiệt độ', 'The temperature outside is very high.', 'Nhiệt độ ngoài trời rất cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'vaccination', 'Noun', '/væksɪˈneɪʃən/', 'vắc-xin', 'I need to get vaccinated against the flu.', 'Tôi cần được tiêm vắc-xin chống lại cúm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'weight', 'Noun', '/weɪt/', 'cân nặng', 'I need to lose weight to get healthier.', 'Tôi cần giảm cân để có sức khỏe tốt hơn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'wellness', 'Noun', '/ˈwɛlnəs/', 'sức khỏe tốt', 'Taking care of your wellness is important.', 'Chăm sóc sức khỏe của bạn là rất quan trọng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 3, 'wound', 'Noun', '/waʊnd/', 'chấn thương', 'The wound is healing slowly.', 'Chấn thương đang hồi phục chậm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'golf', 'Noun', '/ɡɒlf/', 'gôn', 'He loves playing golf on weekends.', 'Anh ấy yêu thích chơi gôn vào cuối tuần.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'tennis', 'Noun', '/ˈtɛnɪs/', 'bóng chuyền', 'She''s an excellent tennis player.', 'Cô ấy là một cầu thủ bóng chuyền xuất sắc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'swim', 'Verb', '/swɪm/', 'bơi', 'I love to swim in the summer.', 'Tôi yêu thích bơi vào mùa hè.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'cycle', 'Verb', '/ˈsaɪkəl/', 'đi xe đạp', 'He likes to cycle around the park.', 'Anh ấy thích đi xe đạp quanh công viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'run', 'Verb', '/rʌn/', 'chạy', 'She likes to run in the morning.', 'Cô ấy yêu thích chạy vào buổi sáng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'team', 'Noun', '/tiːm/', 'đội', 'The football team won the championship.', 'Đội bóng đá đã giành chức vô địch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'score', 'Noun', '/skɔːr/', 'điểm', 'The team scored a goal in the last minute.', 'Đội đã ghi bàn thắng trong phút cuối.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'league', 'Noun', '/liːɡ/', 'liên đoàn', 'The football league is very competitive.', 'Liên đoàn bóng đá rất cạnh tranh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'match', 'Noun', '/mætʃ/', 'trận đấu', 'The match will start at 8pm.', 'Trận đấu sẽ bắt đầu lúc 8 giờ tối.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'player', 'Noun', '/ˈpleɪər/', 'cầu thủ', 'He''s a great player in the football team.', 'Anh ấy là một cầu thủ xuất sắc trong đội bóng đá.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'coach', 'Noun', '/koʊtʃ/', 'hậu vệ', 'The coach is very experienced.', 'Hậu vệ rất có kinh nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'fitness', 'Noun', '/ˈfɪtnəs/', 'sức khỏe thể chất', 'Exercise is important for fitness.', 'Thể dục là rất quan trọng cho sức khỏe thể chất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'training', 'Noun', '/ˈtreɪnɪŋ/', 'huấn luyện', 'The athlete needs regular training.', 'Áthlét cần huấn luyện thường xuyên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'tournament', 'Noun', '/tɔːrnmənt/', 'tourney', 'The tennis tournament is very popular.', 'Tourney bóng chuyền rất phổ biến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'record', 'Noun', '/ˈrɛkɔrd/', 'kỷ lục', 'The athlete broke the record in the marathon.', 'Áthlét đã phá kỷ lục trong marathon.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'spectator', 'Noun', '/ˈspektətər/', 'khán giả', 'The stadium was full of spectators.', 'Sân vận động đầy khán giả.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'referee', 'Noun', '/rɪˈfɛri/', 'trọng tài', 'The referee made a fair decision.', 'Trọng tài đã đưa ra quyết định công bằng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'umpire', 'Noun', '/ˈʌmpaɪər/', 'trọng tài', 'The umpire called a foul.', 'Trọng tài đã gọi lỗi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'spectacle', 'Noun', '/ˈspektəkəl/', 'kịch bản', 'The fireworks display was a spectacle.', 'Hiển thị pháo hoa là một kịch bản.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 4, 'entertainment', 'Noun', '/ˌɛntərˈteɪnmənt/', 'giải trí', 'The concert was a great entertainment.', 'Khuyến khích buổi hòa nhạc là một giải trí tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'job', 'Noun', '/dʒɒb/', 'công việc', 'She''s looking for a job in marketing.', 'Cô ấy đang tìm kiếm một công việc trong lĩnh vực tiếp thị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'work', 'Noun', '/wɜːrk/', 'công việc', 'He''s been working hard all day.', 'Anh ấy đã làm việc chăm chỉ cả ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'employee', 'Noun', '/ɪmˈplɔɪ/', 'nhân viên', 'The company has many employees.', 'Công ty có nhiều nhân viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'employer', 'Noun', '/ɪmˈploʊər/', 'nơi làm việc', 'The employer is responsible for paying taxes.', 'Nơi làm việc có trách nhiệm trả thuế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'salary', 'Noun', '/ˈsæləri/', 'lương', 'He earns a good salary for his job.', 'Anh ấy nhận được một lương tốt cho công việc của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'hour', 'Noun', '/aʊər/', 'giờ', 'She works 8 hours a day.', 'Cô ấy làm việc 8 giờ một ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'shift', 'Noun', '/ʃɪft/', 'ca làm việc', 'He works the night shift.', 'Anh ấy làm việc ca đêm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'team', 'Noun', '/tiːm/', 'đội', 'The team is working on a project.', 'Đội đang làm việc trên một dự án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'project', 'Noun', '/ˈprɒdʒekt/', 'dự án', 'The company is working on a new project.', 'Công ty đang làm việc trên một dự án mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'meeting', 'Noun', '/ˈmiːtɪŋ/', 'hội nghị', 'The meeting will start at 2 PM.', 'Hội nghị sẽ bắt đầu lúc 2 giờ chiều.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'training', 'Noun', '/ˈtreɪnɪŋ/', 'đào tạo', 'The company provides training for its employees.', 'Công ty cung cấp đào tạo cho nhân viên của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'promotion', 'Noun', '/ˌprɒməʊˈneɪʃən/', 'tăng lương', 'She was promoted to a manager position.', 'Cô ấy được thăng chức lên vị trí quản lý.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'retirement', 'Noun', '/ˌrɛtrɪˈmɛnt/', 'hưu trí', 'He''s planning to retire soon.', 'Anh ấy đang lên kế hoạch về hưu sớm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'vacation', 'Noun', '/ˌvækˈseɪʃən/', 'ngày nghỉ', 'She''s going on vacation next week.', 'Cô ấy sẽ đi nghỉ vào tuần sau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'benefit', 'Noun', '/bɪˈnɛfɪt/', 'lợi ích', 'The company offers many benefits to its employees.', 'Công ty cung cấp nhiều lợi ích cho nhân viên của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'career', 'Noun', '/ˈkærɪər/', 'nghề nghiệp', 'She''s building a successful career in law.', 'Cô ấy đang xây dựng một sự nghiệp thành công trong lĩnh vực luật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'hobby', 'Noun', '/ˈhɒbi/', 'hobby', 'He enjoys playing golf as a hobby.', 'Anh ấy thích chơi golf như một sở thích.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 5, 'skill', 'Noun', '/skɪl/', 'kỹ năng', 'She has a skill for painting.', 'Cô ấy có kỹ năng vẽ tranh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'microchip', 'Noun', '/maɪkrəʊtʃɪp/', 'mạch tích hợp', 'The microchip controls the entire system.', 'Mạch tích hợp điều khiển toàn bộ hệ thống.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'algorithm', 'Noun', '/ˈælɡərɪðəm/', 'định luật tính toán', 'The algorithm is too complex to understand.', 'Định luật tính toán quá phức tạp để hiểu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'circuit', 'Noun', '/ˈsɜːrtɪt/', 'hệ thống điện', 'The circuit needs to be repaired.', 'Hệ thống điện cần phải sửa chữa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'software', 'Noun', '/ˈsɒftˌweər/', 'phần mềm', 'The software is outdated and needs to be updated.', 'Phần mềm đã cũ và cần phải được cập nhật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'hardware', 'Noun', '/ˈhɑːdˌweər/', 'phần cứng', 'The hardware is not compatible with the software.', 'Phần cứng không tương thích với phần mềm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'network', 'Noun', '/ˈnɛtwərk/', 'mạng lưới', 'The network is down and cannot be accessed.', 'Mạng lưới bị lỗi và không thể truy cập.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'database', 'Noun', '/ˈdeɪtəbeɪs/', 'cơ sở dữ liệu', 'The database needs to be updated regularly.', 'Cơ sở dữ liệu cần phải được cập nhật thường xuyên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'interface', 'Noun', '/ˈaɪntərfeɪs/', 'phần tiếp xúc', 'The interface is user-friendly and easy to use.', 'Phần tiếp xúc thân thiện với người dùng và dễ sử dụng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'server', 'Noun', '/ˈsɛrvər/', 'máy chủ', 'The server is down and cannot be accessed.', 'Máy chủ bị lỗi và không thể truy cập.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'client', 'Noun', '/ˈklɪnt/', 'khách hàng', 'The client needs to be configured properly.', 'Khách hàng cần phải được cấu hình đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'protocol', 'Noun', '/ˈprɒtəkəl/', 'quy trình', 'The protocol needs to be followed carefully.', 'Quy trình cần phải được tuân thủ cẩn thận.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'scanner', 'Noun', '/ˈskænər/', 'máy quét', 'The scanner is not working properly.', 'Máy quét không hoạt động đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'printer', 'Noun', '/ˈprɪntər/', 'máy in', 'The printer is out of ink and needs to be replaced.', 'Máy in hết mực và cần phải được thay thế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'keyboard', 'Noun', '/ˈkiːbɔːrd/', 'bàn phím', 'The keyboard is not working properly.', 'Bàn phím không hoạt động đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'mouse', 'Noun', '/maʊs/', 'con chuột', 'The mouse is not working properly.', 'Con chuột không hoạt động đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'monitor', 'Noun', '/mɒnɪtər/', 'màn hình', 'The monitor is not working properly.', 'Màn hình không hoạt động đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'modem', 'Noun', '/ˈmoʊdəm/', 'máy điều khiển', 'The modem is not working properly.', 'Máy điều khiển không hoạt động đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'browser', 'Noun', '/ˈbraʊzər/', 'trình duyệt', 'The browser is not working properly.', 'Trình duyệt không hoạt động đúng cách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 6, 'password', 'Noun', '/ˈpæswərd/', 'mật khẩu', 'The password needs to be changed regularly.', 'Mật khẩu cần phải được thay đổi thường xuyên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'street', 'Noun', '/striːt/', 'con đường', 'The street is very crowded today.', 'Con đường này rất đông người hôm nay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'square', 'Noun', '/skweə/', 'phố chợ', 'The square is a popular meeting place.', 'Phố chợ này là nơi họp mặt phổ biến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'park', 'Noun', '/pɑːrk/', 'công viên', 'The park is a great place to relax.', 'Công viên này là nơi tuyệt vời để thư giãn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'library', 'Noun', '/ˈlaɪbrəri/', 'thư viện', 'The library is open on Sundays.', 'Thư viện này mở cửa vào ngày Chủ nhật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'restaurant', 'Noun', '/ˈrestərɑːnt/', 'quán ăn', 'The restaurant serves delicious food.', 'Quán ăn này phục vụ món ăn ngon.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'hotel', 'Noun', '/ˈhoʊtəl/', 'khách sạn', 'The hotel has a beautiful view.', 'Khách sạn này có tầm nhìn tuyệt đẹp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'bank', 'Noun', '/bæŋk/', 'ngân hàng', 'The bank is open from 9 to 5.', 'Ngân hàng này mở cửa từ 9 đến 5.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'station', 'Noun', '/ˈsteɪʃən/', 'bến xe', 'The train station is very busy.', 'Bến xe lửa này rất đông người.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'city', 'Noun', '/ˈsɪti/', 'thành phố', 'The city is very crowded today.', 'Thành phố này rất đông người hôm nay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'town', 'Noun', '/taʊn/', 'thị trấn', 'The town is very quiet.', 'Thị trấn này rất yên tĩnh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'map', 'Noun', '/mæp/', 'bản đồ', 'The map is very helpful.', 'Bản đồ này rất hữu ích.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'direction', 'Noun', '/dɪrɛkʃən/', 'hướng', 'The direction to the park is very clear.', 'Hướng đến công viên này rất rõ ràng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'address', 'Noun', '/əˈdres/', 'địa chỉ', 'The address of the hotel is very easy to find.', 'Địa chỉ của khách sạn này rất dễ tìm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'locate', 'Verb', '/ləʊˈkeɪt/', 'định vị', 'Can you locate the restaurant on the map?', 'Bạn có thể định vị quán ăn trên bản đồ không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'navigate', 'Verb', '/nævɪˈgeɪt/', 'đi đường', 'I need to navigate the city to get to the hotel.', 'Tôi cần đi đường thành phố để đến khách sạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'route', 'Noun', '/ruːt/', 'đường đi', 'The route to the park is very scenic.', 'Đường đi đến công viên này rất đẹp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'sign', 'Noun', '/saɪn/', 'biển hiệu', 'The sign on the road says ''Turn left''.', 'Biển hiệu trên đường này nói ''Về trái''.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 7, 'tourist', 'Noun', '/ˈtʊərɪst/', 'du khách', 'The tourist information center is very helpful.', 'Trung tâm thông tin du khách này rất hữu ích.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'leisure', 'Noun', '/ˈleʒər/', 'thời gian rảnh rỗi', 'I enjoy my leisure time by reading books.', 'Tôi thích thời gian rảnh rỗi bằng việc đọc sách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'relax', 'Verb', '/rɪˈlæks/', 'thư giãn', 'After a long day, I like to relax with a cup of tea.', 'Sau một ngày dài, tôi thích thư giãn với một tách trà.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'vacation', 'Noun', '/vækˈseɪʃən/', 'lễ hội', 'I''m going on vacation to the beach next week.', 'Tôi sẽ đi lễ hội đến bãi biển tuần sau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'entertainment', 'Noun', '/ˌɛntərˈteɪnmənt/', 'giải trí', 'The movie was a great source of entertainment for me.', 'Phim đó là một nguồn giải trí tuyệt vời cho tôi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'hobby', 'Noun', '/ˈhɒbi/', 'hobby', 'My hobby is playing the guitar.', 'Hobby của tôi là chơi guitar.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'recreation', 'Noun', '/ˌriːkriːˈeɪʃən/', 'giải trí', 'The park is a great place for recreation.', 'Công viên là một nơi tuyệt vời cho giải trí.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'amusement', 'Noun', '/əˈmjuːzmənt/', 'giải trí', 'The amusement park was a lot of fun.', 'Công viên giải trí thật tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'leisurely', 'Adverb', '/ˈleʒərli/', 'thời gian rảnh rỗi', 'I like to take a leisurely walk in the park.', 'Tôi thích đi dạo trong công viên một cách thư giãn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'relaxing', 'Adjective', '/rɪˈlæksɪŋ/', 'thư giãn', 'The music is very relaxing.', 'Nhạc đó rất thư giãn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'vacationer', 'Noun', '/vækˈseɪʃənər/', 'người đi lễ hội', 'I''m a vacationer in this beautiful city.', 'Tôi là một người đi lễ hội trong thành phố này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'entertainer', 'Noun', '/ˌɛntərˈteɪnmər/', 'người giải trí', 'The entertainer was very funny.', 'Người giải trí đó rất hài hước.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'recreational', 'Adjective', '/ˌriːkriːˈeɪʃənəl/', 'giải trí', 'The recreational center is a great place to meet new people.', 'Trung tâm giải trí là một nơi tuyệt vời để gặp gỡ những người mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'amusing', 'Adjective', '/əˈmjuːzɪŋ/', 'giải trí', 'The comedian was very amusing.', 'Diễn viên hài đó rất hài hước.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'idle', 'Adjective', '/ˈaɪdəl/', 'không làm việc', 'I was idle for a few hours this morning.', 'Tôi không làm việc trong vài giờ sáng nay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'spare', 'Verb', '/speə/', 'có thời gian rảnh', 'I spare some time to read a book.', 'Tôi có thời gian rảnh để đọc sách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'free', 'Adjective', '/friː/', 'rảnh rỗi', 'I have a free afternoon to relax.', 'Tôi có một buổi chiều rảnh để thư giãn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 8, 'sparetime', 'Noun', '/speəraɪm/', 'thời gian rảnh rỗi', 'I use my spare time to learn a new language.', 'Tôi sử dụng thời gian rảnh rỗi để học một ngôn ngữ mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'celebrate', 'Verb', '/səˈlɛbreɪt/', 'kỷ niệm', 'We will celebrate our anniversary next week.', 'Chúng tôi sẽ kỷ niệm kỷ niệm ngày kỷ niệm của mình vào tuần sau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'event', 'Noun', '/ɪˈvɛnt/', 'sự kiện', 'The event was a huge success.', 'Sự kiện đã thành công lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'festival', 'Noun', '/ˈfɛstɪvəl/', 'lễ hội', 'The festival is happening next weekend.', 'Lễ hội sẽ diễn ra vào cuối tuần này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'guest', 'Noun', '/ɡest/', 'khách', 'The guest speaker will talk about his experiences.', 'Người thuyết trình khách sẽ nói về những kinh nghiệm của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'host', 'Noun', '/hɒst/', 'chủ nhà', 'The host of the party is very friendly.', 'Chủ nhà của bữa tiệc rất thân thiện.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'invite', 'Verb', '/ɪnˈvaɪt/', 'đưa lời mời', 'I will invite my friends to the party.', 'Tôi sẽ mời bạn bè của mình đến bữa tiệc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'perform', 'Verb', '/pərˈfɔrm/', 'thực hiện', 'The band will perform at the concert tonight.', 'Ban nhạc sẽ biểu diễn tại buổi hòa nhạc tonight.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'program', 'Noun', '/ˈproʊgræm/', 'chương trình', 'The program for the festival is very interesting.', 'Chương trình cho lễ hội rất thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'register', 'Verb', '/rɪˈdʒɪstər/', 'đăng ký', 'You need to register for the conference before it starts.', 'Bạn cần đăng ký cho hội nghị trước khi nó bắt đầu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'spectator', 'Noun', '/ˈspektətər/', 'khán giả', 'The spectator was very excited about the game.', 'Khán giả rất phấn khích về trận đấu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'ticket', 'Noun', '/ˈtɪkt/', 'vé', 'You need to buy a ticket to get into the concert.', 'Bạn cần mua vé để vào buổi hòa nhạc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'visitor', 'Noun', '/vɪzɪˈtər/', 'khách viếng thăm', 'The visitor was very impressed by the museum.', 'Khách viếng thăm rất ấn tượng với bảo tàng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'welcome', 'Verb', '/ˈwɛlməʊ/', 'chào đón', 'The host will welcome the guests at the door.', 'Chủ nhà sẽ chào đón khách tại cửa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'attend', 'Verb', '/əˈtɛnd/', 'đến tham dự', 'I will attend the meeting tomorrow.', 'Tôi sẽ đến tham dự cuộc họp ngày mai.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'organize', 'Verb', '/ɔːrɡənaɪz/', 'ổn định', 'The team will organize the festival next month.', 'Đội sẽ tổ chức lễ hội vào tháng sau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'participate', 'Verb', '/ˌpɑrtɪsɪˈpeɪt/', 'tham gia', 'The students will participate in the competition.', 'Học sinh sẽ tham gia cuộc thi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'present', 'Verb', '/ˈprɛznt/', 'trình bày', 'The speaker will present his ideas at the conference.', 'Người thuyết trình sẽ trình bày ý tưởng của mình tại hội nghị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 9, 'sponsor', 'Noun', '/ˈspɒnsər/', 'đồng tổ chức', 'The company is a sponsor of the festival.', 'Công ty là một đồng tổ chức của lễ hội.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'tall', 'Adjective', '/tɔːl/', 'cao', 'He is a tall man.', 'Anh ấy là một người đàn ông cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'short', 'Adjective', '/ʃɔːrt/', 'ngắn', 'The short film was very interesting.', 'Phim ngắn rất thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'fat', 'Adjective', '/fæt/', 'béo', 'He is getting fat because he eats too much.', 'Anh ấy đang trở nên béo vì anh ấy ăn quá nhiều.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'thin', 'Adjective', '/θɪn/', 'mỏng', 'She is very thin because she doesn''t eat much.', 'Cô ấy rất mỏng vì cô ấy không ăn nhiều.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'happy', 'Adjective', '/ˈhæpi/', 'hạnh phúc', 'I am happy to see you.', 'Tôi rất hạnh phúc khi thấy anh ấy.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'sad', 'Adjective', '/sæd/', 'buồn', 'I am sad because I lost my phone.', 'Tôi buồn vì tôi đã mất điện thoại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'old', 'Adjective', '/oʊld/', 'cũ', 'This old car is very slow.', 'Xe cũ này rất chậm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'new', 'Adjective', '/nuː/', 'mới', 'This new phone is very expensive.', 'Điện thoại mới này rất đắt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'big', 'Adjective', '/bɪɡ/', 'lớn', 'This big house is very beautiful.', 'Nhà lớn này rất đẹp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'small', 'Adjective', '/smɔːl/', 'nhỏ', 'This small dog is very cute.', 'Chó nhỏ này rất dễ thương.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'long', 'Adjective', '/lɔŋ/', 'dài', 'This long road is very boring.', 'Đường dài này rất nhàm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'wide', 'Adjective', '/waɪd/', 'rộng', 'This wide river is very deep.', 'Sông rộng này rất sâu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'heavy', 'Adjective', '/ˈhɛvi/', 'nặng', 'This heavy box is very hard to lift.', 'Hộp nặng này rất khó nâng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'light', 'Adjective', '/laɪt/', 'nhẹ', 'This light bag is very easy to carry.', 'Ví nhẹ này rất dễ mang.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'hot', 'Adjective', '/hɒt/', 'nóng', 'This hot coffee is very delicious.', 'Cà phê nóng này rất ngon.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'cold', 'Adjective', '/kɔːld/', 'lạnh', 'This cold water is very refreshing.', 'Nước lạnh này rất dễ chịu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'old', 'Adjective', '/oʊld/', 'cũ', 'This old book is very valuable.', 'Sách cũ này rất quý giá.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'young', 'Adjective', '/jʌŋ/', 'trẻ', 'This young girl is very talented.', 'Cô gái trẻ này rất tài năng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'beautiful', 'Adjective', '/ˌbjuːtɪˈfʊl/', 'xinh đẹp', 'This beautiful garden is very peaceful.', 'Hồ nước đẹp này rất yên bình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('A2', 10, 'ugly', 'Adjective', '/ˈʌɡli/', 'xấu', 'This ugly house is very old.', 'Nhà xấu này rất cũ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'pollute', 'Verb', '/ˈpɒlyuːt/', 'ô nhiễm', 'The factory is polluting the river.', 'Công ty đang ô nhiễm sông.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'recycle', 'Verb', '/rɪˈsaɪkəl/', 'hồi chế', 'We need to recycle more plastic.', 'Chúng ta cần phải hồi chế nhiều nhựa hơn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'climate', 'Noun', '/ˈklaimət/', 'thời tiết', 'The climate in this region is very hot.', 'Thời tiết ở khu vực này rất nóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'sustainable', 'Adjective', '/sʌstənəbəl/', 'sử dụng bền vững', 'We need to adopt sustainable practices in our daily life.', 'Chúng ta cần phải áp dụng các phương pháp sử dụng bền vững trong cuộc sống hàng ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'biodiversity', 'Noun', '/baɪoʊdaɪˈvɛrsɪti/', 'sự đa dạng sinh học', 'The forest is home to a rich biodiversity.', 'Rừng là nơi có sự đa dạng sinh học phong phú.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'greenhouse', 'Noun', '/ˈɡriːnhaʊs/', 'nhà kính', 'The greenhouse is perfect for growing plants in the winter.', 'Nhà kính là nơi lý tưởng để trồng cây vào mùa đông.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'carbon', 'Noun', '/ˈkɑːrbən/', 'carbon', 'Carbon is an essential element for life.', 'Carbon là một nguyên tố quan trọng cho sự sống.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'emission', 'Noun', '/ɪˈmɪʃən/', 'xả thải', 'The factory''s emission is causing pollution.', 'Xả thải của nhà máy đang gây ô nhiễm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'conservation', 'Noun', '/kənˌsɜːrvˈeɪʃən/', 'bảo tồn', 'We need to conserve water and energy.', 'Chúng ta cần phải bảo tồn nước và năng lượng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'fossil', 'Noun', '/ˈfɒsəl/', 'khoáng sản hóa thạch', 'The fossil is a remnant of a dinosaur.', 'Khoáng sản hóa thạch là một phần của khủng long.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'ocean', 'Noun', '/ˈoʊʃən/', 'biển', 'The ocean is home to many different species.', 'Biển là nơi có nhiều loài khác nhau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'atmosphere', 'Noun', '/ətˈmɒsfɪər/', 'khí quyển', 'The atmosphere is essential for life.', 'Khí quyển là một phần quan trọng cho sự sống.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'ecosystem', 'Noun', '/iːˈkoʊsɪstəm/', 'môi trường sống', 'The forest is a delicate ecosystem.', 'Rừng là một hệ sinh thái nhạy cảm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'pollen', 'Noun', '/ˈpɒlən/', 'phấn hoa', 'Pollen is a common allergen.', 'Phấn hoa là một loại dị ứng phổ biến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'solar', 'Adjective', '/ˈsoʊlər/', 'năng lượng mặt trời', 'Solar panels are used to generate electricity.', 'Các tấm pin năng lượng mặt trời được sử dụng để tạo ra điện.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'recyclable', 'Adjective', '/rɪˈsaɪkəbəl/', 'hồi chế được', 'Plastic bottles are recyclable.', 'Bình nhựa là có thể hồi chế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'depletion', 'Noun', '/dɪˈpliːʃən/', 'tình trạng cạn kiệt', 'The depletion of the ocean''s fish population is a concern.', 'Tình trạng cạn kiệt số lượng cá trong đại dương là một mối quan tâm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'habitat', 'Noun', '/həˈbɪtæt/', 'môi trường sống', 'The habitat of the panda is in the mountains.', 'Môi trường sống của gấu trúc là ở núi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 1, 'conservationist', 'Noun', '/kənˌsɜːrvˈeɪʃənɪst/', 'người bảo vệ môi trường', 'The conservationist is fighting to save the forest.', 'Người bảo vệ môi trường đang chiến đấu để cứu rừng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'lecturer', 'Noun', '/ˈlɛktʃərər/', 'giáo sư', 'The lecturer is very experienced.', 'Giáo sư này rất có kinh nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'assignment', 'Noun', '/əsˈnaɪnmənt/', 'bài tập về nhà', 'The teacher gave us an assignment to finish by next week.', 'Giáo viên đã giao cho chúng tôi một bài tập về nhà để hoàn thành trong tuần tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'examination', 'Noun', '/ˌeksəˈmeɪʃən/', 'khảo sát', 'The examination is next week.', 'Khảo sát sẽ diễn ra vào tuần tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'research', 'Noun', '/rɪˈsɜːrtʃ/', 'nghiên cứu', 'The researcher spent years studying the effects of climate change.', 'Nghiên cứu viên đã dành nhiều năm để nghiên cứu tác động của biến đổi khí hậu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'curriculum', 'Noun', '/kəˈrɪkjʊləm/', 'chương trình học', 'The new curriculum includes more emphasis on technology.', 'Chương trình học mới đã đặt trọng tâm nhiều hơn vào công nghệ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'diploma', 'Noun', '/dɪˈplɒmə/', 'bằng cấp', 'She received her diploma in engineering.', 'Cô nhận được bằng cấp về kỹ thuật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'thesis', 'Noun', '/ˈθiːsɪs/', 'tính toán', 'He spent years working on his thesis.', 'Anh ta đã dành nhiều năm để làm việc trên luận án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'tutorial', 'Noun', '/tuːˈtɔːriəl/', 'giảng bài', 'The tutorial is on Friday at 2 PM.', 'Giảng bài sẽ diễn ra vào thứ Năm lúc 2 giờ chiều.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'lectures', 'Noun', '/ˈlɛktʃərz/', 'giảng bài', 'The lectures are on Mondays and Wednesdays.', 'Giảng bài diễn ra vào thứ Hai và thứ Tư.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'assignment', 'Noun', '/əsˈnaɪnmənt/', 'bài tập về nhà', 'The teacher gave us an assignment to finish by next week.', 'Giáo viên đã giao cho chúng tôi một bài tập về nhà để hoàn thành trong tuần tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'examination', 'Noun', '/ˌeksəˈmeɪʃən/', 'khảo sát', 'The examination is next week.', 'Khảo sát sẽ diễn ra vào tuần tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'research', 'Noun', '/rɪˈsɜːrtʃ/', 'nghiên cứu', 'The researcher spent years studying the effects of climate change.', 'Nghiên cứu viên đã dành nhiều năm để nghiên cứu tác động của biến đổi khí hậu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'curriculum', 'Noun', '/kəˈrɪkjʊləm/', 'chương trình học', 'The new curriculum includes more emphasis on technology.', 'Chương trình học mới đã đặt trọng tâm nhiều hơn vào công nghệ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'diploma', 'Noun', '/dɪˈplɒmə/', 'bằng cấp', 'She received her diploma in engineering.', 'Cô nhận được bằng cấp về kỹ thuật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'thesis', 'Noun', '/ˈθiːsɪs/', 'tính toán', 'He spent years working on his thesis.', 'Anh ta đã dành nhiều năm để làm việc trên luận án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'tutorial', 'Noun', '/tuːˈtɔːriəl/', 'giảng bài', 'The tutorial is on Friday at 2 PM.', 'Giảng bài sẽ diễn ra vào thứ Năm lúc 2 giờ chiều.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'lectures', 'Noun', '/ˈlɛktʃərz/', 'giảng bài', 'The lectures are on Mondays and Wednesdays.', 'Giảng bài diễn ra vào thứ Hai và thứ Tư.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'degree', 'Noun', '/ˈdɪɡriː/', 'bằng cấp', 'She earned a degree in business.', 'Cô nhận được bằng cấp về kinh doanh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 2, 'graduation', 'Noun', '/ˌɡrædʒʊˈeɪʃən/', 'tốt nghiệp', 'The graduation ceremony is next week.', 'Lễ tốt nghiệp diễn ra vào tuần tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'art', 'Noun', '/ɑrt/', 'tác phẩm nghệ thuật', 'She is a talented artist.', 'Cô ấy là một nghệ sĩ tài năng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'artist', 'Noun', '/ˈɑrtɪst/', 'người tạo tác nghệ thuật', 'He is a famous artist from Paris.', 'Anh ấy là một nghệ sĩ nổi tiếng từ Paris.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'audience', 'Noun', '/ˈɔːdɪəns/', 'khán giả', 'The audience was very quiet during the play.', 'Khán giả rất im lặng trong vở kịch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'beauty', 'Noun', '/ˈbjuːtɪ/', 'đẹp', 'The beauty of nature is amazing.', 'Đẹp của thiên nhiên thật tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'canvas', 'Noun', '/ˈkænvəs/', 'vải để vẽ tranh', 'She is painting on a large canvas.', 'Cô ấy đang vẽ tranh trên một tấm vải lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'culture', 'Noun', '/ˈkʌltʃər/', 'văn hóa', 'The culture of Japan is very unique.', 'Văn hóa của Nhật Bản rất độc đáo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'dance', 'Verb', '/dɑːns/', 'múa', 'She loves to dance in the evening.', 'Cô ấy yêu thích múa vào buổi tối.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'design', 'Noun', '/dɪˈzaɪn/', 'thiết kế', 'The design of the building is very modern.', 'Thiết kế của tòa nhà rất hiện đại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'entertainment', 'Noun', '/ˌɛntərˈteɪnmənt/', 'giải trí', 'The movie is a great source of entertainment.', 'Phim là một nguồn giải trí tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'festival', 'Noun', '/ˈfɛstɪvəl/', 'lễ hội', 'The music festival was very popular.', 'Lễ hội âm nhạc rất phổ biến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'gallery', 'Noun', '/ˈɡæləri/', 'trường trưng bày nghệ thuật', 'The art gallery is open every day.', 'Trường trưng bày nghệ thuật mở cửa mỗi ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'history', 'Noun', '/hɪˈstɔːri/', 'lịch sử', 'The history of art is very interesting.', 'Lịch sử nghệ thuật rất thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'imagination', 'Noun', '/ɪˌmædʒɪˈneɪʃən/', 'tư duy sáng tạo', 'She has a great imagination for writing stories.', 'Cô ấy có một tư duy sáng tạo tuyệt vời cho việc viết truyện.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'inspiration', 'Noun', '/ˌɪnsəˈpeɪʃən/', 'sáng kiến', 'The beauty of nature is a great inspiration.', 'Đẹp của thiên nhiên là một nguồn sáng kiến tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'music', 'Noun', '/ˈmjuːzɪk/', 'âm nhạc', 'She loves to listen to music in the evening.', 'Cô ấy yêu thích nghe nhạc vào buổi tối.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'museum', 'Noun', '/ˈmjuːzɪəm/', 'trường bảo tàng', 'The museum is open every day.', 'Trường bảo tàng mở cửa mỗi ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'painting', 'Noun', '/ˈpeɪntɪŋ/', 'tranh vẽ', 'She is a talented painter.', 'Cô ấy là một nghệ sĩ vẽ tranh tài năng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'performance', 'Noun', '/ˌpərfərˈmæns/', 'hiệu suất', 'The performance of the play was excellent.', 'Hiệu suất của vở kịch rất xuất sắc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'sculpture', 'Noun', '/ˈskʌltʃər/', 'tượng điêu', 'The sculpture is a great work of art.', 'Tượng điêu là một tác phẩm nghệ thuật tuyệt vời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 3, 'theater', 'Noun', '/ˈθiːətər/', 'nhà hát', 'The theater is open every day.', 'Nhà hát mở cửa mỗi ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'venture', 'Noun', '/ˈvɛntʃər/', 'sự mạo hiểm', 'She decided to take a venture into the tech industry.', 'Cô quyết định tham gia vào ngành công nghệ với sự mạo hiểm đó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'launch', 'Verb', '/lɑːntʃ/', 'bắt đầu', 'The company will launch a new product next month.', 'Công ty sẽ bắt đầu sản phẩm mới vào tháng sau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'market', 'Noun', '/ˈmɑːrkɪt/', 'thị trường', 'The company is trying to enter the market with a new product.', 'Công ty đang cố gắng tham gia thị trường với sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'network', 'Noun', '/ˈnɛtwərk/', 'mạng lưới', 'The company has a strong network of partners and suppliers.', 'Công ty có mạng lưới mạnh mẽ các đối tác và nhà cung cấp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'partner', 'Noun', '/ˈpɑːtərnər/', 'đối tác', 'The company is looking for a partner to invest in the project.', 'Công ty đang tìm kiếm đối tác để đầu tư vào dự án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'invest', 'Verb', '/ɪnˈvɛst/', 'đầu tư', 'The company is investing in a new factory.', 'Công ty đang đầu tư vào một nhà máy mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'strategy', 'Noun', '/ˈstrætɪdʒi/', 'chiến lược', 'The company has a clear strategy for expanding into new markets.', 'Công ty có chiến lược rõ ràng để mở rộng vào thị trường mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'target', 'Noun', '/ˈtɑːrgɪt/', 'mục tiêu', 'The company is setting a target to increase sales by 20%.', 'Công ty đang đặt mục tiêu tăng doanh số 20%.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'brand', 'Noun', '/brænd/', 'thương hiệu', 'The company is trying to build a strong brand in the market.', 'Công ty đang cố gắng xây dựng thương hiệu mạnh mẽ trên thị trường.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'funding', 'Noun', '/ˈfʌndɪŋ/', 'tài trợ', 'The company is seeking funding to launch a new product.', 'Công ty đang tìm kiếm tài trợ để bắt đầu sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'entrepreneur', 'Noun', '/ˌɒntrəˈprɒnə/', 'nhà kinh doanh', 'She is a successful entrepreneur with several businesses.', 'Cô là một nhà kinh doanh thành công với nhiều doanh nghiệp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'innovate', 'Verb', '/ɪˈnɒveɪt/', 'tạo ra ý tưởng mới', 'The company is innovating in the field of renewable energy.', 'Công ty đang tạo ra ý tưởng mới trong lĩnh vực năng lượng tái tạo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'marketplace', 'Noun', '/ˈmɑːrkɪtpleɪs/', 'thị trường', 'The company is trying to enter the marketplace with a new product.', 'Công ty đang cố gắng tham gia thị trường với sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'venture', 'Verb', '/ˈvɛntʃər/', 'mạo hiểm', 'She decided to venture into the tech industry.', 'Cô quyết định tham gia vào ngành công nghệ với sự mạo hiểm đó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'launchpad', 'Noun', '/lɑːntʃpæd/', 'phát triển', 'The company is using a launchpad to develop a new product.', 'Công ty đang sử dụng một nền tảng phát triển để tạo ra sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'synergy', 'Noun', '/ˈsɪnədʒi/', 'sự tương tác', 'The company is looking for synergy between departments.', 'Công ty đang tìm kiếm sự tương tác giữa các bộ phận.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'disrupt', 'Verb', '/dɪsˈrʌpt/', 'phá vỡ', 'The company is trying to disrupt the traditional market with a new product.', 'Công ty đang cố gắng phá vỡ thị trường truyền thống với sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'ecosystem', 'Noun', '/ɪˈkoʊsɪstəm/', 'môi trường', 'The company is trying to create a sustainable ecosystem for its products.', 'Công ty đang cố gắng tạo ra một môi trường bền vững cho sản phẩm của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 4, 'innovation', 'Noun', '/ɪˌnɒveɪʃən/', 'sự đổi mới', 'The company is focusing on innovation to stay competitive.', 'Công ty đang tập trung vào sự đổi mới để duy trì sự cạnh tranh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'broadcast', 'Verb', '/ˈbrɒd.kɑːst/', 'phát sóng', 'The news will be broadcast on TV tonight.', 'Tin tức sẽ được phát sóng trên TV tonight.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'channel', 'Noun', '/ˈtʃæn.əl/', 'kênh', 'Please change the channel to watch the football match.', 'Xin chuyển kênh để xem trận đấu bóng đá.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'clip', 'Verb', '/klɪp/', 'chặt, cắt', 'Can you clip the news article for me?', 'Bạn có thể cắt bài báo tin tức cho tôi không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'comment', 'Noun', '/kəmˈent/', 'bình luận', 'I''d like to comment on the article.', 'Tôi muốn bình luận về bài viết.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'editor', 'Noun', '/ˈed.ɪtər/', 'chủ biên', 'The editor of the newspaper is very experienced.', 'Chủ biên của báo chí rất có kinh nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'headline', 'Noun', '/ˈhæd.laɪn/', 'tiêu đề', 'The headline of the article is very catchy.', 'Tiêu đề của bài viết rất hấp dẫn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'interview', 'Noun', '/ɪnˈtɜː.vjuː/', 'phỏng vấn', 'I''m going to interview the famous actor tomorrow.', 'Tôi sẽ phỏng vấn diễn viên nổi tiếng ngày mai.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'journalist', 'Noun', '/dʒɜːr.nəˈlɪst/', 'nhà báo', 'The journalist is very brave to report on the war.', 'Nhà báo rất dũng cảm để báo cáo về chiến tranh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'magazine', 'Noun', '/mæɡəˈziːn/', 'tạp chí', 'I''m reading a magazine about fashion.', 'Tôi đang đọc tạp chí về thời trang.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'newspaper', 'Noun', '/njuːz.pɛpər/', 'báo chí', 'I''m reading the newspaper to stay up-to-date.', 'Tôi đang đọc báo chí để cập nhật thông tin.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'program', 'Noun', '/ˈproʊ.græm/', 'chương trình', 'The TV program is very entertaining.', 'Chương trình TV rất hấp dẫn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'radio', 'Noun', '/ˈreɪ.ɪ.oʊ/', 'đài phát thanh', 'I''m listening to the radio while driving.', 'Tôi đang nghe đài phát thanh trong khi lái xe.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'reporter', 'Noun', '/rɪˈpɔːrtər/', 'nhà báo', 'The reporter is very brave to report on the war.', 'Nhà báo rất dũng cảm để báo cáo về chiến tranh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'review', 'Verb', '/rɪˈvjuː/', 'đánh giá', 'I''m going to review the new movie tonight.', 'Tôi sẽ đánh giá bộ phim mới tonight.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'script', 'Noun', '/skrɪpt/', 'kịch bản', 'The script of the play is very well-written.', 'Kịch bản của vở kịch rất hay viết.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'series', 'Noun', '/ˈsɪər.iːz/', 'đoạn', 'The TV series is very popular.', 'Đoạn TV rất phổ biến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'television', 'Noun', '/tɪ.vɪˈzɪʊ.ʃən/', 'tivi', 'I''m watching TV while eating dinner.', 'Tôi đang xem tivi trong khi ăn tối.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'transmit', 'Verb', '/trænzˈmɪt/', 'phát sóng', 'The radio station will transmit the news at 6pm.', 'Trạm phát thanh sẽ phát sóng tin tức lúc 6 giờ chiều.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 5, 'viewer', 'Noun', '/ˈvjuː.ər/', 'người xem', 'The viewer of the TV show is very loyal.', 'Người xem chương trình TV rất trung thành.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'family', 'Noun', '/ˈfæm.ɪli/', 'gia đình', 'She comes from a big family.', 'Cô ấy đến từ một gia đình lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'friend', 'Noun', '/frend/', 'bạn', 'He''s a good friend of mine.', 'Anh ấy là một người bạn tốt của tôi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'neighbor', 'Noun', '/ˈneɪbər/', 'người sống gần', 'Be careful not to disturb your neighbor.', 'Cẩn thận đừng làm phiền người sống gần bạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'community', 'Noun', '/kəˈmjuːn.ɪti/', 'xã hội', 'The community center is a great place to meet new people.', 'Trung tâm cộng đồng là một nơi tuyệt vời để gặp gỡ những người mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'culture', 'Noun', '/ˈkʌltʃər/', 'văn hóa', 'The culture of Japan is very different from ours.', 'Văn hóa của Nhật Bản rất khác biệt so với văn hóa của chúng ta.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'religion', 'Noun', '/rɪˈlɪdʒən/', 'tôn giáo', 'Many people in the world practice different religions.', 'Nhiều người trên thế giới thực hành các tôn giáo khác nhau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'society', 'Noun', '/səˈsaɪ.əti/', 'xã hội', 'The society of our country is very developed.', 'Xã hội của đất nước chúng ta rất phát triển.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'tradition', 'Noun', '/trædɪˈtɪʃən/', 'truyền thống', 'We celebrate Christmas as a tradition.', 'Chúng tôi kỷ niệm Giáng sinh như một truyền thống.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'custom', 'Noun', '/ˈkʌstəm/', 'lịch sự', 'It''s a custom to remove your shoes before entering a temple.', 'Lịch sự là thói quen tháo giày trước khi vào đền thờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'etiquette', 'Noun', '/ɪˈtɪkɪt/', 'lễ nghi', 'She knew the etiquette of the royal court.', 'Cô ấy biết lễ nghi của triều đình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'politeness', 'Noun', '/ˌpɒlɪˈtɪnəs/', 'lễ phép', 'He showed great politeness to his guests.', 'Anh ấy thể hiện sự lễ phép lớn lao với khách mời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'kindness', 'Noun', '/ˈkaɪnd.nəs/', 'tình yêu thương', 'She showed kindness to the poor.', 'Cô ấy thể hiện tình yêu thương với người nghèo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'help', 'Verb', '/hɛlp/', 'giúp đỡ', 'Can you help me with this task?', 'Bạn có thể giúp tôi với công việc này không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'support', 'Verb', '/səˈpɔːt/', 'ủng hộ', 'The government will support the economy.', 'Chính phủ sẽ ủng hộ nền kinh tế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'respect', 'Noun', '/rɪˈspɛkt/', 'sự tôn trọng', 'We must respect our elders.', 'Chúng tôi phải tôn trọng người lớn tuổi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'happiness', 'Noun', '/hæp.ɪnəs/', 'hạnh phúc', 'She felt happiness when she got the job.', 'Cô ấy cảm thấy hạnh phúc khi được nhận việc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'friendship', 'Noun', '/ˈfrend.ʃɪp/', 'bạn bè', 'Their friendship lasted for many years.', 'Bề bạn bè của họ kéo dài trong nhiều năm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'love', 'Noun', '/lʌv/', 'tình yêu', 'She felt love for her family.', 'Cô ấy cảm thấy tình yêu với gia đình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'family', 'Noun', '/ˈfæm.ɪli/', 'gia đình', 'She comes from a big family.', 'Cô ấy đến từ một gia đình lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 6, 'neighborhood', 'Noun', '/ˈneɪbərhʊd/', 'khu phố', 'The neighborhood is very quiet.', 'Khu phố rất yên tĩnh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'ambition', 'Noun', '/æmˈbɪʃən/', 'mục tiêu', 'Her ambition is to become a doctor.', 'Mục tiêu của cô ấy là trở thành bác sĩ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'analyze', 'Verb', '/ənˈælɪzaɪz/', 'xử lý, phân tích', 'We need to analyze the data before we can make a decision.', 'Chúng ta cần phân tích dữ liệu trước khi có thể đưa ra quyết định.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'assert', 'Verb', '/əˈsɜːrt/', 'tuyên bố', 'She asserted that she was not responsible for the mistake.', 'Cô tuyên bố rằng cô không phải là người gây ra lỗi đó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'balance', 'Noun', '/ˈbæləns/', 'tính cân bằng', 'She had to balance her work and family life.', 'Cô phải cân bằng giữa công việc và cuộc sống gia đình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'challenge', 'Noun', '/ˈtʃældʒ/', 'thách thức', 'The project was a challenge for the team.', 'Dự án đó là một thách thức đối với đội ngũ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'commit', 'Verb', '/kəˈmɪt/', 'cam kết', 'She committed to helping her friend.', 'Cô cam kết sẽ giúp đỡ bạn của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'confidence', 'Noun', '/kənˈfɪdəns/', 'tự tin', 'He gained confidence after completing the project.', 'Anh ấy có thêm tự tin sau khi hoàn thành dự án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'decide', 'Verb', '/dɪˈsaɪd/', 'quyết định', 'We need to decide what to do next.', 'Chúng ta cần quyết định điều gì tiếp theo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'develop', 'Verb', '/dɪˈvɛləp/', 'phát triển', 'The company is developing new products.', 'Công ty đang phát triển các sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'dream', 'Noun', '/driːm/', 'mộng ước', 'She had a dream about becoming a famous artist.', 'Cô có một giấc mơ về việc trở thành một nghệ sĩ nổi tiếng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'evaluate', 'Verb', '/ɪˈvæljuːeɪt/', 'đánh giá', 'We need to evaluate the performance of the team.', 'Chúng ta cần đánh giá hiệu suất của đội ngũ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'focus', 'Noun', '/ˈfoʊkəs/', 'nhiệt độ', 'She had to focus on her studies.', 'Cô phải tập trung vào việc học tập.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'improve', 'Verb', '/ɪmˈproʊv/', 'tăng tiến', 'The company is trying to improve its services.', 'Công ty đang cố gắng cải thiện dịch vụ của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'influence', 'Noun', '/ɪnˈflʊəns/', 'ảnh hưởng', 'She had a lot of influence on her friends.', 'Cô có ảnh hưởng lớn đối với bạn bè của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'motivate', 'Verb', '/məˈtɪveɪt/', 'động viên', 'The coach motivated the team to win.', 'Hậu vệ động viên đội ngũ để giành chiến thắng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'opportunity', 'Noun', '/ˌɒpəˈtjuːnɪti/', 'cơ hội', 'She took advantage of the opportunity to travel.', 'Cô tận dụng cơ hội để đi du lịch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'potential', 'Noun', '/pəˈtɛnʃəl/', 'sự tiềm ẩn', 'He has a lot of potential to become a great leader.', 'Anh ấy có tiềm năng lớn để trở thành một nhà lãnh đạo xuất sắc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'realize', 'Verb', '/rɪˈaɪlaɪz/', 'nhận ra', 'She realized that she had made a mistake.', 'Cô nhận ra rằng cô đã mắc lỗi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'self-confidence', 'Noun', '/sɛlfkənˈfɪdəns/', 'tự tin', 'He gained self-confidence after completing the project.', 'Anh ấy có thêm tự tin sau khi hoàn thành dự án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'setback', 'Noun', '/ˈsɛt.bæk/', 'trở ngại', 'The project experienced a setback due to the lack of funding.', 'Dự án gặp trở ngại do thiếu nguồn tài trợ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 7, 'strive', 'Verb', '/straɪv/', 'nỗ lực', 'She strives to be the best in her field.', 'Cô nỗ lực để trở thành người xuất sắc trong lĩnh vực của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'experiment', 'Noun', '/ɛksˈpɛrɪmənt/', 'thử nghiệm', 'The scientists conducted an experiment to test the new theory.', 'Các nhà khoa học đã thực hiện một thử nghiệm để kiểm tra lý thuyết mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'innovation', 'Noun', '/ɪnəˈveɪʃən/', 'sự đổi mới', 'The company''s innovation in technology led to significant growth.', 'Sự đổi mới công nghệ của công ty đã dẫn đến sự tăng trưởng đáng kể.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'research', 'Noun', '/rɪˈsɜːrtʃ/', 'nghiên cứu', 'The team conducted research on the effects of climate change.', 'Đội đã thực hiện nghiên cứu về tác động của biến đổi khí hậu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'hypothesis', 'Noun', '/hɪˈpɒθɪsɪs/', 'định đề', 'The scientist''s hypothesis was later proven to be incorrect.', 'Định đề của nhà khoa học sau đó đã được chứng minh là không đúng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'simulate', 'Verb', '/sɪmʊˈleɪt/', 'mô phỏng', 'The researchers simulated the effects of a natural disaster.', 'Các nhà nghiên cứu đã mô phỏng tác động của một thảm họa tự nhiên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'analyze', 'Verb', '/ənˈælɪzaɪz/', 'phân tích', 'The data analyst spent hours analyzing the financial reports.', 'Nhân viên phân tích dữ liệu đã dành nhiều giờ để phân tích báo cáo tài chính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'predict', 'Verb', '/prɪˈdɪkt/', 'đoán trước', 'The meteorologist predicted a storm would hit the city.', 'Nhà khí tượng học đã dự đoán một cơn bão sẽ đánh vào thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'evaluate', 'Verb', '/ɪˈvæliweɪt/', 'đánh giá', 'The teacher evaluated the student''s performance in the exam.', 'Giáo viên đã đánh giá kết quả học tập của học sinh trong kỳ thi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'design', 'Noun', '/dɪˈzaɪn/', 'sáng tạo', 'The architect designed a new building for the city.', 'Kỹ sư kiến trúc đã thiết kế một tòa nhà mới cho thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'prototype', 'Noun', '/ˈproʊtətaɪp/', 'phiên bản thử nghiệm', 'The company created a prototype of the new smartphone.', 'Công ty đã tạo ra một phiên bản thử nghiệm của điện thoại mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'iteration', 'Noun', '/aɪˌtɛˈreɪʃən/', 'lần lặp lại', 'The software development team went through several iterations to perfect the code.', 'Đội phát triển phần mềm đã trải qua nhiều lần lặp lại để hoàn thiện mã nguồn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'validate', 'Verb', '/vælɪˈdeɪt/', 'xác minh', 'The researcher validated the results of the study.', 'Nhà nghiên cứu đã xác minh kết quả nghiên cứu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'iterate', 'Verb', '/aɪˈtɛreɪt/', 'lặp lại', 'The team iterated the design process to improve the product.', 'Đội đã lặp lại quá trình thiết kế để cải thiện sản phẩm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'algorithm', 'Noun', '/ˌælɡəˈrɪðəm/', 'phương pháp giải quyết', 'The computer scientist developed an algorithm to optimize the code.', 'Kỹ sư máy tính đã phát triển một thuật toán để tối ưu hóa mã nguồn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'simulate', 'Verb', '/sɪmʊˈleɪt/', 'mô phỏng', 'The researchers simulated the effects of a natural disaster.', 'Các nhà nghiên cứu đã mô phỏng tác động của một thảm họa tự nhiên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'analyze', 'Verb', '/ənˈælɪzaɪz/', 'phân tích', 'The data analyst spent hours analyzing the financial reports.', 'Nhân viên phân tích dữ liệu đã dành nhiều giờ để phân tích báo cáo tài chính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'predict', 'Verb', '/prɪˈdɪkt/', 'đoán trước', 'The meteorologist predicted a storm would hit the city.', 'Nhà khí tượng học đã dự đoán một cơn bão sẽ đánh vào thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'evaluate', 'Verb', '/ɪˈvæliweɪt/', 'đánh giá', 'The teacher evaluated the student''s performance in the exam.', 'Giáo viên đã đánh giá kết quả học tập của học sinh trong kỳ thi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 8, 'design', 'Noun', '/dɪˈzaɪn/', 'sáng tạo', 'The architect designed a new building for the city.', 'Kỹ sư kiến trúc đã thiết kế một tòa nhà mới cho thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'bus', 'Noun', '/bʌs/', 'xe buýt', 'I take the bus to work every day.', 'Tôi đi xe buýt đến nơi làm việc mỗi ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'station', 'Noun', '/ˈsteɪʃən/', 'bến xe', 'The train station is located in the city center.', 'Bến xe lửa nằm ở trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'ticket', 'Noun', '/ˈtɪkɪt/', 'vé', 'Please buy a ticket before you board the bus.', 'Xin mua vé trước khi lên xe buýt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'route', 'Noun', '/ruːt/', 'đường đi', 'The bus follows a specific route to the city center.', 'Xe buýt đi theo một đường đi cụ thể đến trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'schedule', 'Noun', '/ˈskedʒʊl/', 'lịch trình', 'Please check the schedule for the bus departure time.', 'Xin kiểm tra lịch trình để biết giờ xuất phát của xe buýt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'delay', 'Noun', '/dɪˈleɪ/', 'trễ hẹn', 'The flight was delayed due to bad weather.', 'Chuyến bay bị trễ hẹn do thời tiết xấu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'transfer', 'Verb', '/trænsˈfɜːr/', 'chuyển tuyến', 'You need to transfer to a different bus to get to your destination.', 'Bạn cần chuyển tuyến sang một chiếc xe buýt khác để đến điểm đến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'fare', 'Noun', '/fɛr/', 'giá vé', 'The fare for the taxi ride was very high.', 'Giá vé cho chuyến đi taxi rất cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'park', 'Verb', '/pɑːrk/', 'đỗ xe', 'Please park your car in the designated area.', 'Xin đỗ xe trong khu vực được chỉ định.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'traffic', 'Noun', '/ˈtræfɪk/', 'sự kẹt xe', 'There is heavy traffic on the highway.', 'Có sự kẹt xe nặng nề trên cao tốc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'pedestrian', 'Noun', '/ˌpedɪˈstriːən/', 'người đi bộ', 'The pedestrian crossing is located at the intersection.', 'Đường đi bộ nằm ở giao lộ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'sign', 'Noun', '/saɪn/', 'biển báo', 'The sign on the road indicates the direction to the city center.', 'Biển báo trên đường chỉ hướng đến trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'route', 'Noun', '/ruːt/', 'đường đi', 'The bus follows a specific route to the city center.', 'Xe buýt đi theo một đường đi cụ thể đến trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'schedule', 'Noun', '/ˈskedʒʊl/', 'lịch trình', 'Please check the schedule for the bus departure time.', 'Xin kiểm tra lịch trình để biết giờ xuất phát của xe buýt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'delay', 'Noun', '/dɪˈleɪ/', 'trễ hẹn', 'The flight was delayed due to bad weather.', 'Chuyến bay bị trễ hẹn do thời tiết xấu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'transfer', 'Verb', '/trænsˈfɜːr/', 'chuyển tuyến', 'You need to transfer to a different bus to get to your destination.', 'Bạn cần chuyển tuyến sang một chiếc xe buýt khác để đến điểm đến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'fare', 'Noun', '/fɛr/', 'giá vé', 'The fare for the taxi ride was very high.', 'Giá vé cho chuyến đi taxi rất cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'park', 'Verb', '/pɑːrk/', 'đỗ xe', 'Please park your car in the designated area.', 'Xin đỗ xe trong khu vực được chỉ định.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'traffic', 'Noun', '/ˈtræfɪk/', 'sự kẹt xe', 'There is heavy traffic on the highway.', 'Có sự kẹt xe nặng nề trên cao tốc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'pedestrian', 'Noun', '/ˌpedɪˈstriːən/', 'người đi bộ', 'The pedestrian crossing is located at the intersection.', 'Đường đi bộ nằm ở giao lộ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 9, 'sign', 'Noun', '/saɪn/', 'biển báo', 'The sign on the road indicates the direction to the city center.', 'Biển báo trên đường chỉ hướng đến trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'explore', 'Verb', '/ɛksˈploʊər/', 'khám phá', 'We decided to explore the new city.', 'Chúng tôi quyết định khám phá thành phố mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'tourist', 'Noun', '/ˈtʊərɪst/', 'du khách', 'The tourist information center is located near the train station.', 'Trung tâm thông tin du khách nằm gần ga tàu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'attraction', 'Noun', '/əˈtrækʃən/', 'điểm thu hút', 'The Eiffel Tower is a major attraction in Paris.', 'Tháp Eiffel là một điểm thu hút chính ở Paris.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'itinerary', 'Noun', '/ˌɪtɪnˈɛri/', 'đường đi', 'Can you show me your itinerary for the trip?', 'Bạn có thể cho tôi xem lịch trình của chuyến đi không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'accommodation', 'Noun', '/əkəməˈdeɪʃən/', 'phòng nghỉ', 'We booked a hotel room for our accommodation.', 'Chúng tôi đã đặt phòng khách sạn cho chỗ ở.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'sightseeing', 'Noun', '/ˈsaɪtˌsiːɪŋ/', 'khám phá', 'We spent the day sightseeing in the city.', 'Chúng tôi đã dành cả ngày để khám phá thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'excursion', 'Noun', '/ɛksˈkɜːrʒən/', 'chuyến đi', 'We took an excursion to the nearby island.', 'Chúng tôi đã đi một chuyến đến đảo gần đó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'passport', 'Noun', '/ˈpæs.pɔːrt/', 'hộ chiếu', 'Don''t forget to bring your passport when traveling abroad.', 'Hãy không quên mang hộ chiếu khi đi nước ngoài.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'visa', 'Noun', '/ˈviːsə/', 'giấy phép nhập cảnh', 'You need a visa to enter the United States.', 'Bạn cần giấy phép nhập cảnh để vào Mỹ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'currency', 'Noun', '/ˈkɜːrɛnsi/', 'tiền tệ', 'The currency in Japan is the yen.', 'Tiền tệ ở Nhật Bản là yên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'budget', 'Noun', '/ˈbʌdʒɪt/', 'kế hoạch tài chính', 'We need to make a budget for our trip.', 'Chúng tôi cần lập kế hoạch tài chính cho chuyến đi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'transport', 'Verb', '/trænˈspɔːrt/', 'chuyển tải', 'We need to transport our luggage to the hotel.', 'Chúng tôi cần chuyển tải hành lý đến khách sạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'accommodate', 'Verb', '/əkəməˈdeɪt/', 'cung cấp chỗ ở', 'The hotel will accommodate us for the night.', 'Khách sạn sẽ cung cấp chỗ ở cho chúng tôi trong đêm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'navigate', 'Verb', '/nævɪˈgeɪt/', 'đi đường', 'We need to navigate the city to get to the airport.', 'Chúng tôi cần đi đường thành phố để đến sân bay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'orientation', 'Noun', '/ˌɔːriˈeɪʃən/', 'hướng dẫn', 'The hotel staff will give us an orientation about the city.', 'Nhân viên khách sạn sẽ hướng dẫn chúng tôi về thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'itinerary', 'Noun', '/ˌɪtɪnˈɛri/', 'đường đi', 'Can you show me your itinerary for the trip?', 'Bạn có thể cho tôi xem lịch trình của chuyến đi không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'exciting', 'Adjective', '/ɛksˈsaɪtɪŋ/', 'thú vị', 'The city has many exciting attractions.', 'Thành phố có nhiều điểm thu hút thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B1', 10, 'relax', 'Verb', '/rɪˈlæks/', 'thư giãn', 'We need to relax after the long trip.', 'Chúng tôi cần thư giãn sau chuyến đi dài.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'budget', 'Noun', '/ˈbʌdʒɪt/', 'kế hoạch tài chính', 'The company needs to create a budget for the new project.', 'Công ty cần tạo một kế hoạch tài chính cho dự án mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'capital', 'Noun', '/ˈkæpɪtəl/', 'tài sản ròng', 'The company''s capital is increasing every year.', 'Tài sản ròng của công ty đang tăng lên mỗi năm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'credit', 'Noun', '/ˈkrɛdɪt/', 'sự tín nhiệm', 'She has good credit and can get a loan easily.', 'Cô có tín nhiệm tốt và có thể vay tiền dễ dàng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'debt', 'Noun', '/debt/', 'nợ', 'He has a lot of debt from his credit cards.', 'Anh ấy có nhiều nợ từ thẻ tín dụng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'economy', 'Noun', '/ɪˈkɒnəmi/', 'tình hình tài chính', 'The country''s economy is growing rapidly.', 'Tình hình tài chính của quốc gia đang phát triển nhanh chóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'expense', 'Noun', '/ɪkˈspens/', 'chi phí', 'The company has a lot of expenses for marketing.', 'Công ty có nhiều chi phí cho quảng cáo.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'finance', 'Noun', '/ˈfaɪnəns/', 'tài chính', 'She works in finance and helps people with their investments.', 'Cô làm việc trong lĩnh vực tài chính và giúp người dân với các khoản đầu tư.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'income', 'Noun', '/ˈɪnkəm/', 'số tiền thu nhập', 'He has a high income from his job.', 'Anh ấy có thu nhập cao từ công việc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'invest', 'Verb', '/ɪnˈvɛst/', 'đầu tư', 'She invested in a new startup company.', 'Cô đã đầu tư vào một công ty khởi nghiệp mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'investor', 'Noun', '/ɪnˈvɛstər/', 'người đầu tư', 'He is a successful investor and has made a lot of money.', 'Anh ấy là một nhà đầu tư thành công và đã kiếm được nhiều tiền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'market', 'Noun', '/ˈmɑːrkɪt/', 'thị trường', 'The company is trying to enter the market with a new product.', 'Công ty đang cố gắng vào thị trường với một sản phẩm mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'profit', 'Noun', '/ˈprɒfɪt/', 'lợi nhuận', 'The company made a lot of profit last year.', 'Công ty đã kiếm được nhiều lợi nhuận trong năm ngoái.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'rate', 'Noun', '/reɪt/', 'tỷ lệ', 'The interest rate is very high right now.', 'Tỷ lệ lãi suất rất cao vào lúc này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'save', 'Verb', '/seɪv/', 'lưu trữ', 'She tries to save money every month.', 'Cô cố gắng tiết kiệm tiền mỗi tháng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'spend', 'Verb', '/spend/', 'chi tiêu', 'He likes to spend his money on travel.', 'Anh ấy thích chi tiêu tiền vào du lịch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'stock', 'Noun', '/stɒk/', 'cổ phiếu', 'She bought some stock in the company.', 'Cô đã mua cổ phiếu của công ty.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'tax', 'Noun', '/tæks/', 'thuế', 'He has to pay a lot of tax on his income.', 'Anh ấy phải trả một số tiền thuế lớn trên thu nhập của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'trade', 'Noun', '/treɪd/', 'chuyển nhượng', 'The country is trying to increase its trade with other nations.', 'Quốc gia đang cố gắng tăng cường thương mại với các quốc gia khác.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 1, 'wealth', 'Noun', '/weɪlθ/', 'tài sản', 'He has a lot of wealth and can afford to travel anywhere.', 'Anh ấy có nhiều tài sản và có thể đi du lịch bất cứ nơi nào.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'strategic', 'Adjective', '/strætɪdʒɪk/', 'đúng chiến lược', 'The company''s strategic plan is to expand globally.', 'Kế hoạch chiến lược của công ty là mở rộng ra toàn cầu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'synergy', 'Noun', '/ˈsɪnəɡri/', 'tác động cộng hưởng', 'The company is looking for synergy between departments.', 'Công ty đang tìm kiếm sự tương tác giữa các bộ phận để tạo ra hiệu quả cao hơn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'diversify', 'Verb', '/dɪˈvɛrsɪfaɪ/', 'tái cơ cấu', 'The company is trying to diversify its product line.', 'Công ty đang cố gắng đa dạng hóa sản phẩm của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'benchmark', 'Noun', '/ˈbɛn.tʃmaɾk/', 'điểm chuẩn', 'The company''s sales figures are a benchmark for the industry.', 'Số liệu doanh số của công ty là tiêu chuẩn cho ngành công nghiệp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'restructure', 'Verb', '/rɪˈstrʌktʃər/', 'phân loại lại', 'The company is restructuring its management team.', 'Công ty đang tái cấu trúc đội ngũ quản lý.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'outsourcing', 'Noun', '/ˈaʊt.saʊtɪŋ/', 'quản lý bên ngoài', 'The company is considering outsourcing its IT department.', 'Công ty đang xem xét việc quản lý bên ngoài bộ phận công nghệ thông tin.');
