INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'motivate', 'Verb', '/məʊˈtɪveɪt/', 'động viên', 'The manager is trying to motivate her team to work harder.', 'Giám đốc đang cố gắng động viên đội ngũ của mình làm việc chăm chỉ hơn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 2, 'strategic', 'Adjective', '/strætɪdʒɪk/', 'đúng chiến lược', 'The company''s strategic plan is to expand globally.', 'Kế hoạch chiến lược của công ty là mở rộng ra toàn cầu.');
