INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'citizen', 'Noun', '/ˈsɪtɪzən/', 'người công dân', 'She is a proud citizen of this country.', 'Cô ấy tự hào là công dân của nước này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'justice', 'Noun', '/ˈdʒʌstɪs/', 'tình trạng công bằng', 'The judge delivered a verdict of justice.', 'Hộ thẩm phán đưa ra phán quyết công bằng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'punish', 'Verb', '/ˈpʌnɪʃ/', 'phạt tội', 'The court will punish the criminal.', 'Tòa án sẽ phạt tội phạm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'sentence', 'Noun', '/ˈsɛntəns/', 'phán quyết', 'The judge read out the sentence.', 'Hộ thẩm phán đọc phán quyết.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'crime', 'Noun', '/krɑɪm/', 'tội phạm', 'The police are investigating the crime.', 'Cảnh sát đang điều tra tội phạm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'punishment', 'Noun', '/ˈpʌnɪʃmənt/', 'phạt tội', 'The punishment was severe.', 'Phạt tội là nghiêm khắc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'lawyer', 'Noun', '/ˈloʊjər/', 'luật sư', 'The lawyer argued the case.', 'Luật sư tranh luận vụ án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'court', 'Noun', '/kɔːrt/', 'tòa án', 'The court will hear the case tomorrow.', 'Tòa án sẽ nghe vụ án ngày mai.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'judge', 'Noun', '/dʒʌdʒ/', 'thẩm phán', 'The judge made a fair decision.', 'Thẩm phán đưa ra phán quyết công bằng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'rights', 'Noun', '/raɪts/', 'quyền lợi', 'Everyone has the right to freedom.', 'Mọi người đều có quyền tự do.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'freedom', 'Noun', '/ˈfriːdəm/', 'tự do', 'She fought for freedom.', 'Cô ấy đấu tranh cho tự do.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'equality', 'Noun', '/ɪˈkwɔːlɪti/', 'tình trạng bình đẳng', 'The principle of equality is important.', 'Tính chất bình đẳng là quan trọng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'democracy', 'Noun', '/dɪˈmɒkrəsi/', 'chủ nghĩa dân chủ', 'Democracy is the best form of government.', 'Chủ nghĩa dân chủ là hình thức tốt nhất của chính quyền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'citizenship', 'Noun', '/sɪˈtɪzənʃɪp/', 'quyền công dân', 'She became a citizen of the country.', 'Cô ấy trở thành công dân của nước này.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'social', 'Adjective', '/ˈsoʊʃəl/', 'liên quan đến xã hội', 'The social worker helped the family.', 'Lao động xã hội giúp đỡ gia đình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'society', 'Noun', '/ˈsɒsɪəti/', 'xã hội', 'The society is very diverse.', 'Xã hội rất đa dạng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'human', 'Adjective', '/ˈhjuːmən/', 'con người', 'The human rights organization helped the victims.', 'Tổ chức quyền con người giúp đỡ nạn nhân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'humanity', 'Noun', '/hjuːˈmænɪti/', 'con người', 'The humanity of the doctor was admirable.', 'Con người của bác sĩ đáng kính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'culture', 'Noun', '/ˈkʌltʃər/', 'văn hóa', 'The culture of the country is very rich.', 'Văn hóa của nước này rất phong phú.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 3, 'tradition', 'Noun', '/ˈtrædɪʃən/', 'truyền thống', 'The tradition of the family is very important.', 'Truyền thống của gia đình rất quan trọng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'gene', 'Noun', '/dʒiːn/', 'di truyền', 'The gene was isolated and sequenced.', 'Di truyền này được phân lập và mã hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'mutation', 'Noun', '/mjuːˈteɪʃən/', 'sự biến đổi di truyền', 'The mutation caused the disease.', 'Sự biến đổi này gây ra bệnh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'protein', 'Noun', '/ˈproʊ.tiːn/', 'chất đạm', 'The protein was synthesized in the lab.', 'Chất đạm này được tổng hợp trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'enzyme', 'Noun', '/ɛnˈzaɪm/', 'hợp chất xúc tác', 'The enzyme was used to break down the sugar.', 'Hợp chất xúc tác này được sử dụng để phân hủy đường.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'cell', 'Noun', '/sɛl/', 'tế bào', 'The cell was studied under a microscope.', 'Tế bào này được nghiên cứu dưới kính hiển vi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'tissue', 'Noun', '/ˈtɪʃ.uː/', 'tạng', 'The tissue was transplanted into the patient.', 'Tạng này được chuyển vào bệnh nhân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'organ', 'Noun', '/ˈɔːr.gən/', 'tạng', 'The organ was removed during surgery.', 'Tạng này được loại bỏ trong phẫu thuật.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'organism', 'Noun', '/ɔːrˈɡanɪzəm/', 'sinh vật', 'The organism was studied in the lab.', 'Sinh vật này được nghiên cứu trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'pathogen', 'Noun', '/ˈpæθ.ɒdʒən/', 'nguyên nhân gây bệnh', 'The pathogen was identified as a virus.', 'Nguyên nhân gây bệnh này được xác định là một loại virus.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'vaccine', 'Noun', '/ˈvæksɪn/', 'vắc xin', 'The vaccine was administered to the patient.', 'Vắc xin này được tiêm vào bệnh nhân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'gene expression', 'Noun', '/dʒiːn ɪkˈspres.ʃən/', 'giải trình di truyền', 'The gene expression was studied in the lab.', 'Giải trình di truyền này được nghiên cứu trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'mutation rate', 'Noun', '/mjuːˈteɪʃən reɪt/', 'tỷ lệ biến đổi di truyền', 'The mutation rate was measured in the experiment.', 'Tỷ lệ biến đổi này được đo trong thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'protein structure', 'Noun', '/ˈproʊ.tiːn strʌktʃər/', 'cấu trúc chất đạm', 'The protein structure was studied using X-ray crystallography.', 'Cấu trúc chất đạm này được nghiên cứu bằng phương pháp X-quang tán xạ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'enzyme kinetics', 'Noun', '/ɛnˈzaɪm kɪˈnɛtɪks/', 'kinh tế học hợp chất xúc tác', 'The enzyme kinetics was studied in the lab.', 'Kinh tế học hợp chất xúc tác này được nghiên cứu trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'cell signaling', 'Noun', '/sɛl saɪnˈtɪlɪŋ/', 'tín hiệu tế bào', 'The cell signaling was studied in the lab.', 'Tín hiệu tế bào này được nghiên cứu trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'tissue engineering', 'Noun', '/ˈtɪʃ.uː ɛŋˈdʒɪnɪərɪŋ/', 'kỹ thuật tạo tạng', 'The tissue engineering was used to create a new organ.', 'Kỹ thuật tạo tạng này được sử dụng để tạo ra một tạng mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'organ transplantation', 'Noun', '/ˈɔːr.gən trænzˈplæntɪtʃən/', 'chuyển tạng', 'The organ transplantation was performed in the hospital.', 'Chuyển tạng này được thực hiện trong bệnh viện.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'pathogenesis', 'Noun', '/ˌpæθ.əˈdʒɛnɪsɪs/', 'sự hình thành bệnh', 'The pathogenesis was studied in the lab.', 'Sự hình thành bệnh này được nghiên cứu trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 4, 'vaccine development', 'Noun', '/væksɪn dɛvəlˈpmənt/', 'phát triển vắc xin', 'The vaccine development was performed in the lab.', 'Phát triển vắc xin này được thực hiện trong phòng thí nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'global', 'Adjective', '/ˈɡloʊbəl/', 'toàn cầu', 'The company has a global presence.', 'Công ty có sự hiện diện toàn cầu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'multinational', 'Adjective', '/mʌltɪˈneɪʃənəl/', 'tập đoàn đa quốc gia', 'The company is a multinational corporation.', 'Công ty là một tập đoàn đa quốc gia.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'outsourcing', 'Noun', '/ˈaʊtaʊtsɔːrɪŋ/', 'quản lý ngoài', 'The company is outsourcing some of its operations.', 'Công ty đang quản lý ngoài một số hoạt động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'sourcing', 'Noun', '/ˈsɔːrsɪŋ/', 'tìm kiếm nguồn', 'The company is sourcing new suppliers for its products.', 'Công ty đang tìm kiếm nguồn cung cấp mới cho sản phẩm của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'trade', 'Noun', '/treɪd/', 'chuyển đổi hàng hóa', 'The country is increasing its trade with neighboring countries.', 'Quốc gia đang tăng cường thương mại với các quốc gia láng giềng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'tariff', 'Noun', '/ˈtærɪf/', 'thuế quan', 'The government is imposing a tariff on imported goods.', 'Chính phủ đang áp dụng thuế quan đối với hàng hóa nhập khẩu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'export', 'Verb', '/ɛksˈpɔːrt/', 'xuất khẩu', 'The company is exporting its products to many countries.', 'Công ty đang xuất khẩu sản phẩm của mình đến nhiều quốc gia.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'import', 'Verb', '/ɪmˈpɔːrt/', 'nhập khẩu', 'The country is importing oil from other countries.', 'Quốc gia đang nhập khẩu dầu mỏ từ các quốc gia khác.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'globalization', 'Noun', '/ˌɡloʊbəlɪˈzeɪʃən/', 'toàn cầu hóa', 'The company is experiencing the effects of globalization.', 'Công ty đang trải qua tác động của toàn cầu hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'multicultural', 'Adjective', '/mʌltɪˈkʌltʃərəl/', 'đa văn hóa', 'The city is a multicultural community.', 'Thành phố là một cộng đồng đa văn hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'outsider', 'Noun', '/ˈaʊstaɪdər/', 'người ngoài cuộc', 'The outsider was not familiar with the company''s policies.', 'Người ngoài cuộc không quen thuộc với các chính sách của công ty.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'sustainability', 'Noun', '/ˌsʌstənəˈbɪlɪti/', 'sự bền vững', 'The company is committed to sustainability in its operations.', 'Công ty cam kết thực hiện sự bền vững trong các hoạt động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'transnational', 'Adjective', '/trænzˈnæʃənəl/', 'quốc tế', 'The company is a transnational corporation.', 'Công ty là một tập đoàn quốc tế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'diversity', 'Noun', '/dɪˈvɜːrsɪti/', 'đa dạng', 'The company values diversity in its workforce.', 'Công ty coi trọng đa dạng trong lực lượng lao động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'global citizen', 'Noun', '/ˌɡloʊbəl ˈsɪtɪzən/', 'người công dân toàn cầu', 'The global citizen is concerned about climate change.', 'Người công dân toàn cầu quan tâm đến biến đổi khí hậu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'multilingual', 'Adjective', '/mʌltɪˈlɪŋɡwɪəl/', 'đa ngôn ngữ', 'The company values multilingual employees.', 'Công ty coi trọng nhân viên đa ngôn ngữ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'outsourced', 'Adjective', '/ˈaʊstaʊtsɪd/', 'đã được quản lý ngoài', 'The company outsourced some of its operations.', 'Công ty đã quản lý ngoài một số hoạt động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'sourcing strategy', 'Noun', '/ˈsɔːrsɪŋ ˈstrætɪdʒi/', 'chiến lược tìm kiếm nguồn', 'The company is developing a sourcing strategy for its products.', 'Công ty đang phát triển chiến lược tìm kiếm nguồn cho sản phẩm của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 5, 'trade agreement', 'Noun', '/treɪd əˈɡriːmənt/', 'thỏa thuận thương mại', 'The country signed a trade agreement with its neighboring countries.', 'Quốc gia đã ký thỏa thuận thương mại với các quốc gia láng giềng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'habit', 'Noun', '/ˈhæbɪt/', 'thói quen', 'She has a habit of biting her nails.', 'Cô có thói quen nhai móng tay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'instinct', 'Noun', '/ˈɪnstɪŋkt/', 'tính tự nhiên', 'The cat''s instinct is to hunt small animals.', 'Tính tự nhiên của mèo là săn bắt động vật nhỏ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'motivation', 'Noun', '/ˌmɒtɪˈveɪʃən/', 'sự kích thích', 'Her motivation for studying is to get a good job.', 'Sự kích thích của cô để học tập là để có được một công việc tốt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'personality', 'Noun', '/ˌpɜːrsəˈnælɪti/', 'tính cách', 'He has a strong personality and is not afraid to speak his mind.', 'Anh có tính cách mạnh mẽ và không sợ nói lên ý kiến của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'psychology', 'Noun', '/ˌsaɪkəˈlɒdʒi/', 'tâm lý học', 'She is studying psychology at university.', 'Cô đang học tâm lý học tại đại học.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'self-control', 'Noun', '/ˌsɛlfkənˈtrɒl/', 'kiểm soát bản thân', 'He needs to work on his self-control to avoid procrastination.', 'Anh cần phải làm việc trên kiểm soát bản thân để tránh trì hoãn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'social', 'Adjective', '/ˈsɒʃəl/', 'liên quan đến xã hội', 'The social media platform has millions of users.', 'Mạng xã hội có hàng triệu người dùng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'suggestion', 'Noun', '/ˈsʌdʒestʃən/', 'gợi ý', 'I have a suggestion for improving the project.', 'Tôi có một gợi ý để cải thiện dự án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'trait', 'Noun', '/treɪt/', 'tính cách', 'Honesty is a trait that is valued in any profession.', 'Sự trung thực là một tính cách được đánh giá cao trong bất kỳ nghề nghiệp nào.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'unconscious', 'Adjective', '/ʌnˈkɒnʃəs/', 'không ý thức', 'He was unconscious after the accident.', 'Anh không ý thức sau tai nạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'behavior', 'Noun', '/bɪˈhævɪər/', 'làm theo thói quen', 'Her behavior is very polite.', 'Làm theo thói quen của cô rất lịch sự.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'cognition', 'Noun', '/kɒɡˈnɪʃən/', 'tình trạng nhận thức', 'Cognition is a key aspect of human intelligence.', 'Tình trạng nhận thức là một khía cạnh quan trọng của trí thông minh con người.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'emotional', 'Adjective', '/ɪˈmɒʃənəl/', 'liên quan đến cảm xúc', 'The emotional support of her friends helped her through the tough time.', 'Sự hỗ trợ cảm xúc của bạn bè giúp cô vượt qua thời gian khó khăn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'intelligence', 'Noun', '/ˌɪntɪliˈdʒəns/', 'trí thông minh', 'He has a high level of intelligence and is very curious.', 'Anh có trình độ trí thông minh cao và rất tò mò.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'motivate', 'Verb', '/ˈmɒtɪveɪt/', 'động viên', 'The coach motivated the team to win the game.', 'Hậu vệ động viên đội để giành chiến thắng trận đấu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'person', 'Noun', '/ˈpɜːr.sən/', 'người', 'He is a kind person and always helps others.', 'Anh là một người tốt bụng và luôn giúp đỡ người khác.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'psychologist', 'Noun', '/ˌsaɪkəˈlɒdʒɪst/', 'tâm lý học', 'She is a psychologist and helps people with mental health issues.', 'Cô là một tâm lý học và giúp đỡ người với các vấn đề sức khỏe tâm thần.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'self-awareness', 'Noun', '/ˌsɛlfəˈwɛr.nəs/', 'tình trạng nhận thức bản thân', 'Developing self-awareness is an important part of personal growth.', 'Phát triển tình trạng nhận thức bản thân là một phần quan trọng của sự phát triển cá nhân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 6, 'socialization', 'Noun', '/ˌsɒʃəl.aɪˈzeɪʃən/', 'quá trình xã hội hóa', 'Socialization is an important part of childhood development.', 'Quá trình xã hội hóa là một phần quan trọng của sự phát triển của trẻ em.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'resume', 'Noun', '/rɛz.uːˈmeɪ/', 'tài liệu xin việc', 'She spent hours updating her resume before the job interview.', 'Cô ấy đã dành nhiều giờ để cập nhật hồ sơ xin việc trước cuộc phỏng vấn việc làm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'interview', 'Noun', '/ɪnˈtɛrvjuː/', 'phỏng vấn', 'The job interview will take place next week.', 'Cuộc phỏng vấn việc làm sẽ diễn ra tuần tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'candidate', 'Noun', '/kænˈdɪdət/', 'tài năng', 'The candidate for the CEO position will be announced next month.', 'Người được đề cử cho vị trí CEO sẽ được công bố vào tháng tới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'recruit', 'Verb', '/rɪˈkruːt/', 'tuyển dụng', 'The company is recruiting new staff members.', 'Công ty đang tuyển dụng nhân viên mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'salary', 'Noun', '/ˈsæləri/', 'lương', 'The salary for the new job is higher than expected.', 'Lương cho công việc mới cao hơn dự kiến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'benefit', 'Noun', '/bɪˈnɛfɪt/', 'lợi ích', 'The company offers health benefits to its employees.', 'Công ty cung cấp các lợi ích về sức khỏe cho nhân viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'career', 'Noun', '/ˈkærɪər/', 'sự nghiệp', 'She has had a successful career in finance.', 'Cô ấy đã có sự nghiệp thành công trong lĩnh vực tài chính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'network', 'Noun', '/ˈnɛtwərk/', 'mạng lưới', 'The company has a strong network of contacts in the industry.', 'Công ty có một mạng lưới liên hệ mạnh mẽ trong ngành.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'training', 'Noun', '/ˈtreɪnɪŋ/', 'đào tạo', 'The company offers training programs for its employees.', 'Công ty cung cấp các chương trình đào tạo cho nhân viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'promotion', 'Noun', '/prəˈmuːʃən/', 'thăng tiến', 'She was promoted to a management position after a year.', 'Cô ấy được thăng chức lên vị trí quản lý sau một năm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'retirement', 'Noun', '/rɪˈtɪər.mənt/', 'hưu trí', 'He retired from his job after 30 years of service.', 'Anh ấy nghỉ hưu sau 30 năm phục vụ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'unemployment', 'Noun', '/ʌn.ɪmˈploɪ.mənt/', 'bất động sản', 'The country is experiencing high levels of unemployment.', 'Nước này đang trải qua mức độ thất nghiệp cao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'vacation', 'Noun', '/vækˈseɪʃən/', 'ngày nghỉ', 'She is taking a vacation to relax and recharge.', 'Cô ấy đang đi nghỉ để thư giãn và tái tạo năng lượng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'hiring', 'Noun', '/ˈhaɪərɪŋ/', 'tuyển dụng', 'The company is hiring new staff members.', 'Công ty đang tuyển dụng nhân viên mới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'layoff', 'Noun', '/ˈleɪ.ɔf/', 'thất nghiệp', 'The company had to lay off many employees due to financial difficulties.', 'Công ty đã phải sa thải nhiều nhân viên do khó khăn tài chính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'salary', 'Noun', '/ˈsæləri/', 'lương', 'The salary for the new job is higher than expected.', 'Lương cho công việc mới cao hơn dự kiến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'benefit', 'Noun', '/bɪˈnɛfɪt/', 'lợi ích', 'The company offers health benefits to its employees.', 'Công ty cung cấp các lợi ích về sức khỏe cho nhân viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'career', 'Noun', '/ˈkærɪər/', 'sự nghiệp', 'She has had a successful career in finance.', 'Cô ấy đã có sự nghiệp thành công trong lĩnh vực tài chính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'network', 'Noun', '/ˈnɛtwərk/', 'mạng lưới', 'The company has a strong network of contacts in the industry.', 'Công ty có một mạng lưới liên hệ mạnh mẽ trong ngành.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 7, 'training', 'Noun', '/ˈtreɪnɪŋ/', 'đào tạo', 'The company offers training programs for its employees.', 'Công ty cung cấp các chương trình đào tạo cho nhân viên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'algorithm', 'Noun', '/ˈælɡərɪðəm/', 'cách giải quyết vấn đề', 'The algorithm is too complex to understand.', 'Cách giải quyết vấn đề này quá phức tạp để hiểu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'artificial', 'Adjective', '/ɑːrtɪˈfɪʃəl/', 'nhân tạo', 'Artificial intelligence is a growing field.', 'Trí tuệ nhân tạo đang là một lĩnh vực phát triển nhanh chóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'bias', 'Noun', '/baɪəs/', 'tư duy thiên vị', 'The algorithm has a bias towards certain groups.', 'Cách giải quyết vấn đề này có thiên vị đối với một số nhóm người.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'compute', 'Verb', '/kəmˈpyuːt/', 'tính toán', 'The computer can compute complex calculations quickly.', 'Máy tính có thể tính toán các phép toán phức tạp nhanh chóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'data', 'Noun', '/ˈdætə/', 'thông tin', 'The data suggests a trend.', 'Thông tin này cho thấy một xu hướng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'deep', 'Adjective', '/diːp/', 'sâu', 'The deep learning model is very accurate.', 'Mô hình học sâu rất chính xác.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'engine', 'Noun', '/ɪnˈdʒɪn/', 'máy móc', 'The engine of the car is very powerful.', 'Máy móc của xe hơi rất mạnh mẽ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'expert', 'Noun', '/ˈɛkspɜːrt/', 'chuyên gia', 'The expert in AI is a renowned speaker.', 'Chuyên gia về trí tuệ nhân tạo là một diễn giả nổi tiếng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'hypothesis', 'Noun', '/haɪˈpɒθɪsɪs/', 'định lý', 'The hypothesis is supported by the data.', 'Định lý này được hỗ trợ bởi thông tin.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'intelligence', 'Noun', '/ˌɪntɪˈliːdəns/', 'trí tuệ', 'Artificial intelligence is a growing field.', 'Trí tuệ nhân tạo đang là một lĩnh vực phát triển nhanh chóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'learn', 'Verb', '/lɜːrn/', 'học', 'The AI system can learn from data.', 'Hệ thống trí tuệ nhân tạo có thể học hỏi từ thông tin.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'machine', 'Noun', '/ˈmɑːʃɪn/', 'máy móc', 'The machine can perform complex calculations.', 'Máy móc này có thể thực hiện các phép toán phức tạp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'model', 'Noun', '/ˈmoʊdəl/', 'mô hình', 'The model of the car is very accurate.', 'Mô hình của xe hơi rất chính xác.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'network', 'Noun', '/ˈnɛtwərk/', 'mạng lưới', 'The network of computers is very fast.', 'Mạng lưới máy tính này rất nhanh chóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'predict', 'Verb', '/prɪˈdɪkt/', 'đoán trước', 'The AI system can predict the outcome.', 'Hệ thống trí tuệ nhân tạo có thể dự đoán kết quả.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'problem', 'Noun', '/ˈprɒbləm/', 'vấn đề', 'The problem is too complex to solve.', 'Vấn đề này quá phức tạp để giải quyết.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'recognize', 'Verb', '/rɛkəɡˈnaɪz/', 'nhận biết', 'The AI system can recognize faces.', 'Hệ thống trí tuệ nhân tạo có thể nhận biết khuôn mặt.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'solve', 'Verb', '/sɒlv/', 'giải quyết', 'The algorithm can solve complex problems.', 'Cách giải quyết vấn đề này có thể giải quyết các vấn đề phức tạp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'system', 'Noun', '/ˈsɪstəm/', 'hệ thống', 'The AI system is very efficient.', 'Hệ thống trí tuệ nhân tạo này rất hiệu quả.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 8, 'technology', 'Noun', '/tɛknəˈlɒdʒi/', 'công nghệ', 'The technology is very advanced.', 'Công nghệ này rất tiên tiến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'export', 'Verb', '/ɛksˈpɔːrt/', 'xuất khẩu', 'The company will export electronics to Asia.', 'Công ty sẽ xuất khẩu điện tử sang châu Á.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'tariff', 'Noun', '/ˈtærɪf/', 'thuế quan', 'The government imposed a tariff on imported cars.', 'Chính phủ đã áp dụng thuế quan đối với ô tô nhập khẩu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'commodity', 'Noun', '/kəmˈɒdɪtē/', 'sản phẩm hàng hóa', 'The company specializes in trading commodities.', 'Công ty chuyên kinh doanh hàng hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'currency', 'Noun', '/ˈkɜːrənsi/', 'tiền tệ', 'The exchange rate of the currency has changed.', 'Tỷ giá hối đoái của tiền tệ đã thay đổi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'customs', 'Noun', '/ˈkʌstəmz/', 'thủ tục hải quan', 'You need to fill out customs forms when importing goods.', 'Bạn cần điền vào các biểu mẫu hải quan khi nhập khẩu hàng hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'freight', 'Noun', '/freɪt/', 'hàng hóa vận chuyển', 'The freight train is carrying heavy machinery.', 'Tàu hỏa chở hàng hóa nặng nề.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'import', 'Verb', '/ɪmˈpɔːrt/', 'nhập khẩu', 'The company will import electronics from China.', 'Công ty sẽ nhập khẩu điện tử từ Trung Quốc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'invoice', 'Noun', '/ɪnˈvaɪs/', 'hóa đơn', 'Please pay the invoice within 30 days.', 'Xin vui lòng thanh toán hóa đơn trong 30 ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'logistics', 'Noun', '/ˈlɒdʒɪstɪks/', 'hàng hóa vận chuyển', 'The company specializes in logistics and transportation.', 'Công ty chuyên kinh doanh logistics và vận tải.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'market', 'Noun', '/ˈmɑːrkɪt/', 'thị trường', 'The company will participate in the international market.', 'Công ty sẽ tham gia thị trường quốc tế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'merchandise', 'Noun', '/mərˈtʃændɪs/', 'hàng hóa', 'The store sells a variety of merchandise.', 'Cửa hàng bán nhiều loại hàng hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'negotiate', 'Verb', '/nɪˈɡəʊʃɪeɪt/', 'thương lượng', 'The company will negotiate with the supplier.', 'Công ty sẽ thương lượng với nhà cung cấp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'order', 'Noun', '/ˈɔːrdər/', 'đơn hàng', 'Please place your order by the end of the day.', 'Xin vui lòng đặt hàng trước khi kết thúc ngày.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'quota', 'Noun', '/ˈkwɒtə/', 'số lượng hạn chế', 'The government has set a quota for imported goods.', 'Chính phủ đã đặt hạn ngạch cho hàng hóa nhập khẩu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'shipping', 'Noun', '/ˈʃɪpɪŋ/', 'vận chuyển', 'The company specializes in shipping and logistics.', 'Công ty chuyên kinh doanh vận chuyển và logistics.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'tariff', 'Noun', '/ˈtærɪf/', 'thuế quan', 'The government imposed a tariff on imported cars.', 'Chính phủ đã áp dụng thuế quan đối với ô tô nhập khẩu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'trade', 'Verb', '/treɪd/', 'kinh doanh', 'The company will trade with other countries.', 'Công ty sẽ kinh doanh với các quốc gia khác.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'transport', 'Verb', '/trænˈspɔːrt/', 'vận chuyển', 'The company specializes in transportation and logistics.', 'Công ty chuyên kinh doanh vận tải và logistics.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 9, 'warehouse', 'Noun', '/ˈwɛrhaʊs/', 'kho hàng', 'The company has a large warehouse for storing merchandise.', 'Công ty có một kho hàng lớn để lưu trữ hàng hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'broadcast', 'Noun', '/ˈbrɒd.kɑːst/', 'báo chí', 'The news will be broadcast at 8pm.', 'Tin tức sẽ được phát sóng lúc 8 giờ tối.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'channel', 'Noun', '/ˈtʃæn.əl/', 'kênh truyền hình', 'Can you change the channel to watch the football match?', 'Bạn có thể đổi kênh để xem trận đấu bóng đá không?');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'column', 'Noun', '/ˈkɒl.əm/', 'cột tin', 'The newspaper has a column about politics.', 'Tạp chí có một cột tin về chính trị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'editor', 'Noun', '/ˈɛd.ɪtər/', 'biên tập viên', 'The editor of the newspaper is very strict.', 'Biên tập viên của tạp chí rất nghiêm khắc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'headline', 'Noun', '/ˈhæd.laɪn/', 'tiêu đề', 'The headline of the article is very attention-grabbing.', 'Tiêu đề của bài viết rất thu hút sự chú ý.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'interview', 'Noun', '/ɪnˈtɜː.vjuː/', 'phỏng vấn', 'The journalist will conduct an interview with the politician.', 'Nhà báo sẽ phỏng vấn chính trị gia.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'journalist', 'Noun', '/dʒɜːr.ˈnæl.ɪst/', 'nhà báo', 'The journalist is very good at researching stories.', 'Nhà báo rất giỏi trong việc nghiên cứu tin tức.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'media', 'Noun', '/ˈmiː.diə/', 'truyền thông', 'The media has a big influence on society.', 'Truyền thông có ảnh hưởng lớn đến xã hội.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'network', 'Noun', '/ˈnɛt.wərk/', 'mạng lưới', 'The company has a large network of employees.', 'Công ty có một mạng lưới nhân viên lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'newspaper', 'Noun', '/ˈnjuːz.pæpər/', 'tạp chí', 'The newspaper is very popular among young people.', 'Tạp chí rất phổ biến trong giới trẻ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'press', 'Verb', '/prɛs/', 'phát', 'The newspaper will press the story tomorrow.', 'Tạp chí sẽ phát tin tức vào ngày mai.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'program', 'Noun', '/ˈproʊ.ɡræm/', 'chương trình', 'The TV program is very entertaining.', 'Chương trình truyền hình rất thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'reporter', 'Noun', '/rɪˈpɔːrtər/', 'nhà báo', 'The reporter is very good at researching stories.', 'Nhà báo rất giỏi trong việc nghiên cứu tin tức.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'review', 'Noun', '/rɪˈvjuː/', 'đánh giá', 'The review of the movie was very positive.', 'Đánh giá của bộ phim rất tích cực.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'scene', 'Noun', '/siːn/', 'kịch', 'The scene of the movie is very dramatic.', 'Kịch của bộ phim rất kịch tính.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'series', 'Noun', '/ˈsɪər.iːz/', 'đài', 'The TV series is very popular among young people.', 'Đài truyền hình rất phổ biến trong giới trẻ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'show', 'Noun', '/ʃoʊ/', 'chương trình', 'The TV show is very entertaining.', 'Chương trình truyền hình rất thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'sponsor', 'Noun', '/ˈspɑːnsər/', 'đại diện', 'The company is the sponsor of the charity event.', 'Công ty là đại diện của sự kiện từ thiện.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'station', 'Noun', '/ˈsteɪ.ʃən/', 'trạm', 'The radio station is very popular among young people.', 'Trạm phát thanh rất phổ biến trong giới trẻ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('B2', 10, 'television', 'Noun', '/tɪ.vɪˈzɪ.ʃən/', 'truyền hình', 'The family is watching television in the living room.', 'Gia đình đang xem truyền hình trong phòng khách.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomacy', 'Noun', '/dɪˈplɒməsi/', 'kỹ năng ngoại giao', 'The ambassador used her diplomacy to resolve the conflict.', 'Tổng lãnh sự sử dụng kỹ năng ngoại giao để giải quyết xung đột.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomat', 'Noun', '/dɪˈplɒmæt/', 'người ngoại giao', 'The diplomat met with the foreign minister to discuss trade agreements.', 'Người ngoại giao gặp với bộ trưởng ngoại giao để thảo luận về các thỏa thuận thương mại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic', 'Adjective', '/dɪˈplɒmætɪk/', 'liên quan đến ngoại giao', 'The diplomatic efforts of the government were successful in resolving the crisis.', 'Nỗ lực ngoại giao của chính phủ đã thành công trong việc giải quyết khủng hoảng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'embassy', 'Noun', '/ɛmˈbæsi/', 'lãnh sự quán', 'The embassy was located in the heart of the city.', 'Lãnh sự quán nằm ở trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'foreign', 'Adjective', '/ˈfɔːrɪn/', 'nước ngoài', 'The foreign minister met with the ambassador to discuss trade agreements.', 'Bộ trưởng ngoại giao gặp với tổng lãnh sự để thảo luận về các thỏa thuận thương mại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'international', 'Adjective', '/ˌɪntərˈnæʃənəl/', 'quốc tế', 'The international community came together to address the global crisis.', 'Thế giới quốc tế đã cùng nhau giải quyết khủng hoảng toàn cầu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'negotiate', 'Verb', '/nɪˈɡəʊɪeɪt/', 'thảo luận', 'The two countries negotiated a trade agreement.', 'Hai quốc gia đã thảo luận và đạt được thỏa thuận thương mại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'negotiation', 'Noun', '/nɪˌɡəʊɪˈeɪʃən/', 'quá trình thảo luận', 'The negotiation between the two countries was successful.', 'Quá trình thảo luận giữa hai quốc gia đã thành công.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic relations', 'Noun', '/dɪˌplɒmætɪk ˈreɪʃənz/', 'quan hệ ngoại giao', 'The two countries established diplomatic relations in 1990.', 'Hai quốc gia đã thiết lập quan hệ ngoại giao vào năm 1990.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic immunity', 'Noun', '/dɪˌplɒmætɪk ɪˈmjuːnɪti/', 'tính miễn trừ ngoại giao', 'The diplomat enjoyed diplomatic immunity in the host country.', 'Người ngoại giao đã được miễn trừ ngoại giao trong quốc gia chủ nhà.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic mission', 'Noun', '/dɪˌplɒmætɪk ˈmɪʃən/', 'nhiệm vụ ngoại giao', 'The diplomat was sent on a diplomatic mission to the host country.', 'Người ngoại giao đã được cử đi thực hiện nhiệm vụ ngoại giao tại quốc gia chủ nhà.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic protocol', 'Noun', '/dɪˌplɒmætɪk ˈprəʊtəkəl/', 'quy trình ngoại giao', 'The diplomatic protocol of the host country was followed during the visit.', 'Quy trình ngoại giao của quốc gia chủ nhà đã được tuân thủ trong chuyến thăm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic recognition', 'Noun', '/dɪˌplɒmætɪk ˌrɛkəɡˈnɪʃən/', 'tình trạng công nhận ngoại giao', 'The country was granted diplomatic recognition by the international community.', 'Quốc gia đã được quốc tế công nhận tình trạng ngoại giao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic relations', 'Noun', '/dɪˌplɒmætɪk ˈreɪʃənz/', 'quan hệ ngoại giao', 'The two countries established diplomatic relations in 1990.', 'Hai quốc gia đã thiết lập quan hệ ngoại giao vào năm 1990.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic immunity', 'Noun', '/dɪˌplɒmætɪk ɪˈmjuːnɪti/', 'tính miễn trừ ngoại giao', 'The diplomat enjoyed diplomatic immunity in the host country.', 'Người ngoại giao đã được miễn trừ ngoại giao trong quốc gia chủ nhà.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic mission', 'Noun', '/dɪˌplɒmætɪk ˈmɪʃən/', 'nhiệm vụ ngoại giao', 'The diplomat was sent on a diplomatic mission to the host country.', 'Người ngoại giao đã được cử đi thực hiện nhiệm vụ ngoại giao tại quốc gia chủ nhà.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 1, 'diplomatic protocol', 'Noun', '/dɪˌplɒmætɪk ˈprəʊtəkəl/', 'quy trình ngoại giao', 'The diplomatic protocol of the host country was followed during the visit.', 'Quy trình ngoại giao của quốc gia chủ nhà đã được tuân thủ trong chuyến thăm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'hypothesis', 'Noun', '/hɒpˈθɛsɪs/', 'đồ án nghiên cứu', 'The researcher presented her hypothesis at the conference.', 'Nhà nghiên cứu đã trình bày giả thuyết của mình tại hội nghị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'methodology', 'Noun', '/mɛθɒdɒlˈɒdʒi/', 'phương pháp nghiên cứu', 'The researcher described her methodology in the introduction.', 'Nhà nghiên cứu đã mô tả phương pháp nghiên cứu của mình trong phần giới thiệu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'paradigm', 'Noun', '/ˈpærədɪm/', 'mô hình nghiên cứu', 'The new paradigm in physics has revolutionized our understanding of the universe.', 'Mô hình mới trong vật lý đã thay đổi cách chúng ta hiểu về vũ trụ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'phenomenon', 'Noun', '/fɪˈnɒmɪnən/', 'sự kiện nghiên cứu', 'The phenomenon of climate change has been extensively studied.', 'Sự kiện biến đổi khí hậu đã được nghiên cứu rộng rãi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'rigor', 'Noun', '/ˈrɪɡər/', 'chất lượng nghiên cứu', 'The researcher emphasized the importance of rigor in her study.', 'Nhà nghiên cứu nhấn mạnh tầm quan trọng của chất lượng nghiên cứu trong nghiên cứu của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'specify', 'Verb', '/ˈspɛsɪfaɪ/', 'xác định rõ', 'The researcher specified the methodology used in the study.', 'Nhà nghiên cứu đã xác định rõ phương pháp nghiên cứu được sử dụng trong nghiên cứu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'systematic', 'Adjective', '/sɪˈstɛmətɪk/', 'lập trình', 'The researcher used a systematic approach to analyze the data.', 'Nhà nghiên cứu đã sử dụng phương pháp lập trình để phân tích dữ liệu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'theoretical', 'Adjective', '/θiːˈɒritɪkəl/', 'lý thuyết', 'The researcher''s theoretical framework was widely accepted.', 'Cấu trúc lý thuyết của nhà nghiên cứu đã được chấp nhận rộng rãi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'validate', 'Verb', '/vælɪˈdeɪt/', 'xác minh', 'The researcher validated the results of the study.', 'Nhà nghiên cứu đã xác minh kết quả của nghiên cứu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'variable', 'Noun', '/ˈværiəbəl/', 'biến số', 'The researcher identified several variables that affected the outcome.', 'Nhà nghiên cứu đã xác định được nhiều biến số ảnh hưởng đến kết quả.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'verifiable', 'Adjective', '/vɛrɪˈfaɪəbəl/', 'xác minh được', 'The data was verifiable through multiple sources.', 'Dữ liệu có thể được xác minh thông qua nhiều nguồn khác nhau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'vulnerable', 'Adjective', '/vʌlnərəbəl/', 'mở rộng', 'The researcher highlighted the vulnerable population in her study.', 'Nhà nghiên cứu đã nhấn mạnh nhóm dân số dễ bị tổn thương trong nghiên cứu của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'academic', 'Adjective', '/əˈkædɛmɪk/', 'học thuật', 'The researcher was an academic expert in her field.', 'Nhà nghiên cứu là một chuyên gia học thuật trong lĩnh vực của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'empirical', 'Adjective', '/ɛmˈpɪrɪkəl/', 'thực nghiệm', 'The researcher used an empirical approach to analyze the data.', 'Nhà nghiên cứu đã sử dụng phương pháp thực nghiệm để phân tích dữ liệu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'interdisciplinary', 'Adjective', '/ˌɪntərˈdɪsɪplɪnəri/', 'nghiên cứu đa ngành', 'The researcher worked on an interdisciplinary project.', 'Nhà nghiên cứu đã làm việc trên một dự án nghiên cứu đa ngành.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'methodical', 'Adjective', '/mɛθədɪkl/', 'lập trình', 'The researcher used a methodical approach to analyze the data.', 'Nhà nghiên cứu đã sử dụng phương pháp lập trình để phân tích dữ liệu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'normative', 'Adjective', '/ˈnɔːrmətɪv/', 'định hướng', 'The researcher''s normative framework was widely accepted.', 'Cấu trúc định hướng của nhà nghiên cứu đã được chấp nhận rộng rãi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 2, 'paradigmatic', 'Adjective', '/ˌpærədɪˈɡæmɪk/', 'mô hình', 'The researcher''s paradigmatic approach was widely adopted.', 'Phương pháp mô hình của nhà nghiên cứu đã được áp dụng rộng rãi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'narrative', 'Noun', '/ˈnærətɪv/', 'câu chuyện', 'The novel is a narrative about love and loss.', 'Tác phẩm tiểu thuyết này là một câu chuyện về tình yêu và mất mát.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'lexicography', 'Noun', '/ˌlek.sɪˈkrɑ.fɪ/', 'ngôn ngữ học', 'She is a lexicographer specializing in English vocabulary.', 'Cô ấy là một nhà ngôn ngữ học chuyên về từ vựng tiếng Anh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'etymology', 'Noun', '/ɪˌtɒməˈlaɪ/', 'nguồn gốc từ', 'The etymology of the word ''computer'' is fascinating.', 'Nguồn gốc từ ''máy tính'' thật thú vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'syntax', 'Noun', '/ˈsæn.tæks/', 'cấu trúc câu', 'Understanding syntax is crucial for writing clear sentences.', 'Hiểu về cấu trúc câu là rất quan trọng để viết các câu rõ ràng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'semantics', 'Noun', '/sɪˈmæntɪks/', 'ý nghĩa từ', 'Semantics is a crucial aspect of language learning.', 'Ý nghĩa từ là một phần quan trọng của việc học ngôn ngữ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'morphology', 'Noun', '/ˌmɔrfəˈlɒdʒi/', 'hình thái từ', 'Morphology is essential for understanding word formation.', 'Hình thái từ là rất quan trọng để hiểu về việc hình thành từ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'idiom', 'Noun', '/ˈaɪdɪəm/', 'cụm từ', 'The idiom ''break a leg'' means ''good luck''.', 'Cụm từ ''mất cánh'' có nghĩa là ''chúc may mắn''.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'metaphor', 'Noun', '/ˈmɛtəfɔr/', 'so sánh ẩn dụ', 'The city is a jungle, full of dangers.', 'Thành phố là một khu rừng, đầy nguy hiểm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'alliteration', 'Noun', '/ˌælɪˈtɛrɪtən/', 'lặp chữ', 'The alliteration in the poem is very effective.', 'Lặp chữ trong bài thơ rất hiệu quả.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'onomatopoeia', 'Noun', '/ɒnəˌmætəˈpiːə/', 'tính âm thanh', 'The onomatopoeia ''buzz'' imitates the sound of a bee.', 'Tính âm thanh ''buzz'' mô phỏng tiếng ong.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'personification', 'Noun', '/ˌpərsənɪfɪˈkeɪʃən/', 'tranh tượng', 'The wind is crying, it''s so cold.', 'Mưa gió đang khóc, thật lạnh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'hyperbole', 'Noun', '/haɪˈpərbəli/', 'lệch lạc', 'I''m so hungry I could eat a whole elephant.', 'Tôi đói quá, tôi có thể ăn cả một con voi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'irony', 'Noun', '/aɪˈrɒni/', 'từ ngữ iron', 'The fire station caught on fire.', 'Trung tâm chữa cháy bị cháy.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'satire', 'Noun', '/ˈsætɪər/', 'tư tưởng châm biếm', 'The satirical article is meant to be humorous.', 'Bài viết châm biếm này nhằm mục đích hài hước.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'symbolism', 'Noun', '/ˌsɪmbəˈlɪzəm/', 'biểu tượng', 'The red rose symbolizes love and passion.', 'Hoa hồng đỏ biểu tượng cho tình yêu và đam mê.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'imagery', 'Noun', '/ɪˈmædʒəri/', 'hình ảnh', 'The poet uses imagery to describe the sunset.', 'Tác giả sử dụng hình ảnh để mô tả hoàng hôn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'allusion', 'Noun', '/əˈluːʒən/', 'tỏa chiếu', 'The novel alludes to the myth of Orpheus and Eurydice.', 'Tác phẩm tiểu thuyết này trích dẫn từ truyện cổ tích Orpheus và Eurydice.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'metaphysical', 'Adjective', '/ˌmɛtəˈfɪzɪkəl/', 'vật lý học', 'The metaphysical novel explores the meaning of life.', 'Tác phẩm tiểu thuyết vật lý học này khám phá ý nghĩa của cuộc sống.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 3, 'existential', 'Adjective', '/ɛɡˈzɪstɛnʃəl/', 'tồn tại', 'The existential novel explores the human condition.', 'Tác phẩm tiểu thuyết tồn tại này khám phá tình trạng con người.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'exist', 'Verb', '/ɛɡˈzɪst/', 'có tồn tại', 'The idea exists in many cultures.', 'Ý tưởng tồn tại trong nhiều nền văn hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'phenomenon', 'Noun', '/fɪnəˈmɪnən/', 'sự kiện', 'The phenomenon of climate change is a major concern.', 'Sự kiện biến đổi khí hậu là một mối quan tâm lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'ontology', 'Noun', '/ɒnˈtɒlədʒi/', 'tư tưởng về tồn tại', 'The philosopher''s ontology is based on the concept of being.', 'Tư tưởng của nhà triết học dựa trên khái niệm về tồn tại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'epistemology', 'Noun', '/ɛpɪˈstɛmələdʒi/', 'tư tưởng về tri thức', 'The epistemology of the scientist is based on empirical evidence.', 'Tư tưởng của nhà khoa học dựa trên bằng chứng thực nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'teleology', 'Noun', '/tɛlɪˈɒlədʒi/', 'tư tưởng về mục đích', 'The teleology of the universe is still a topic of debate.', 'Tư tưởng về mục đích của vũ trụ vẫn còn là một chủ đề tranh luận.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'metaphysics', 'Noun', '/mɛtəˈfɪzɪks/', 'tư tưởng siêu hình', 'The metaphysics of the philosopher is based on the concept of substance.', 'Tư tưởng siêu hình của nhà triết học dựa trên khái niệm về chất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'determinism', 'Noun', '/dɪtərˈmɪnɪzəm/', 'tư tưởng về duyên', 'The determinism of the universe is a topic of debate among philosophers.', 'Tư tưởng về duyên của vũ trụ vẫn còn là một chủ đề tranh luận giữa các nhà triết học.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'nihilism', 'Noun', '/naɪˈɪlɪzəm/', 'tư tưởng về vô nghĩa', 'The nihilism of the philosopher is a result of his pessimistic worldview.', 'Tư tưởng về vô nghĩa của nhà triết học là kết quả của quan điểm thế giới quan tiêu cực của ông.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'existentialism', 'Noun', '/ɛksɪstɛnˈʃəlɪzəm/', 'tư tưởng về tồn tại', 'The existentialism of the philosopher is based on the concept of individual freedom.', 'Tư tưởng về tồn tại của nhà triết học dựa trên khái niệm về tự do cá nhân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'absurdity', 'Noun', '/əbˈsɜːrdɪti/', 'tư tưởng về vô lý', 'The absurdity of the situation is what makes it so humorous.', 'Tư tưởng về vô lý của tình huống đó là điều khiến nó trở nên hài hước.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'paradox', 'Noun', '/ˈpærədɒks/', 'tư tưởng về nghịch lý', 'The paradox of the liar is a classic example of a self-referential paradox.', 'Tư tưởng về nghịch lý của kẻ nói dối là một ví dụ kinh điển về nghịch lý tự tham chiếu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'dialectic', 'Noun', '/daɪˈæltɪk/', 'tư tưởng về đối thoại', 'The dialectic of the philosopher is based on the concept of thesis, antithesis, and synthesis.', 'Tư tưởng về đối thoại của nhà triết học dựa trên khái niệm về lập luận, phản lập luận và tổng hợp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'hermeneutics', 'Noun', '/hɜːrmɪˈnuːtɪks/', 'tư tưởng về giải thích', 'The hermeneutics of the scholar is based on the concept of contextual understanding.', 'Tư tưởng về giải thích của học giả dựa trên khái niệm về hiểu biết trong bối cảnh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'ontology', 'Noun', '/ɒnˈtɒlədʒi/', 'tư tưởng về tồn tại', 'The ontology of the philosopher is based on the concept of being.', 'Tư tưởng về tồn tại của nhà triết học dựa trên khái niệm về tồn tại.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'epistemology', 'Noun', '/ɛpɪˈstɛmələdʒi/', 'tư tưởng về tri thức', 'The epistemology of the scientist is based on empirical evidence.', 'Tư tưởng về tri thức của nhà khoa học dựa trên bằng chứng thực nghiệm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'teleology', 'Noun', '/tɛlɪˈɒlədʒi/', 'tư tưởng về mục đích', 'The teleology of the universe is still a topic of debate.', 'Tư tưởng về mục đích của vũ trụ vẫn còn là một chủ đề tranh luận.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 4, 'metaphysics', 'Noun', '/mɛtəˈfɪzɪks/', 'tư tưởng siêu hình', 'The metaphysics of the philosopher is based on the concept of substance.', 'Tư tưởng siêu hình của nhà triết học dựa trên khái niệm về chất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'legislation', 'Noun', '/ˌledʒɪˈsteɪʃən/', 'luật pháp', 'The new legislation aims to protect the environment.', 'Luật mới nhằm mục đích bảo vệ môi trường.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'regulation', 'Noun', '/ˌredʒʌˈleɪʃən/', 'quy định', 'The government has introduced new regulations to control pollution.', 'Chính phủ đã đưa ra các quy định mới để kiểm soát ô nhiễm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'policy', 'Noun', '/ˈpɒlɪsi/', 'chính sách', 'The government has announced a new policy to reduce poverty.', 'Chính phủ đã công bố một chính sách mới để giảm nghèo đói.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'management', 'Noun', '/ˈmænɪdʒmənt/', 'quản lý', 'The company has a good management team to lead the project.', 'Công ty có một đội ngũ quản lý tốt để lãnh đạo dự án.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'governance', 'Noun', '/ˈɡʌv.nəns/', 'quản trị', 'The country has a good governance system to ensure transparency.', 'Quốc gia có một hệ thống quản trị tốt để đảm bảo sự minh bạch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'transparency', 'Noun', '/trænˈspærənsi/', 'sự minh bạch', 'The company has promised to increase transparency in their business practices.', 'Công ty đã hứa sẽ tăng cường sự minh bạch trong các hoạt động kinh doanh của họ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'accountability', 'Noun', '/ˌækaʊntəˈbɪlɪti/', 'trách nhiệm', 'The government has promised to increase accountability in their decision-making process.', 'Chính phủ đã hứa sẽ tăng cường trách nhiệm trong quá trình ra quyết định của họ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'bureaucracy', 'Noun', '/ˌbjʊərəʊˈkrɑːsi/', 'chính quyền', 'The country has a complex bureaucracy that makes it difficult to get things done.', 'Quốc gia có một hệ thống chính quyền phức tạp khiến việc thực hiện các công việc trở nên khó khăn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'reform', 'Noun', '/ˈriːfɔːm/', 'cải cách', 'The government has introduced reforms to improve the education system.', 'Chính phủ đã đưa ra các cải cách để cải thiện hệ thống giáo dục.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'legitimacy', 'Noun', '/ˌledʒɪˈtɪməsi/', 'sự hợp pháp', 'The new government has struggled to establish its legitimacy in the eyes of the people.', 'Chính phủ mới đã gặp khó khăn trong việc thiết lập sự hợp pháp trong mắt người dân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'democracy', 'Noun', '/dɪˈmɒkrəsi/', 'chính quyền dân chủ', 'The country has a democratic system of government.', 'Quốc gia có một hệ thống chính quyền dân chủ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'participation', 'Noun', '/ˌpɑːtɪsɪˈpeɪʃən/', 'sự tham gia', 'The government encourages participation from citizens in the decision-making process.', 'Chính phủ khuyến khích sự tham gia của công dân trong quá trình ra quyết định.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'transparency', 'Noun', '/trænˈspærənsi/', 'sự minh bạch', 'The company has promised to increase transparency in their business practices.', 'Công ty đã hứa sẽ tăng cường sự minh bạch trong các hoạt động kinh doanh của họ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'accountability', 'Noun', '/ˌækaʊntəˈbɪlɪti/', 'trách nhiệm', 'The government has promised to increase accountability in their decision-making process.', 'Chính phủ đã hứa sẽ tăng cường trách nhiệm trong quá trình ra quyết định của họ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'bureaucracy', 'Noun', '/ˌbjʊərəʊˈkrɑːsi/', 'chính quyền', 'The country has a complex bureaucracy that makes it difficult to get things done.', 'Quốc gia có một hệ thống chính quyền phức tạp khiến việc thực hiện các công việc trở nên khó khăn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'reform', 'Noun', '/ˈriːfɔːm/', 'cải cách', 'The government has introduced reforms to improve the education system.', 'Chính phủ đã đưa ra các cải cách để cải thiện hệ thống giáo dục.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'legitimacy', 'Noun', '/ˌledʒɪˈtɪməsi/', 'sự hợp pháp', 'The new government has struggled to establish its legitimacy in the eyes of the people.', 'Chính phủ mới đã gặp khó khăn trong việc thiết lập sự hợp pháp trong mắt người dân.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 5, 'democracy', 'Noun', '/dɪˈmɒkrəsi/', 'chính quyền dân chủ', 'The country has a democratic system of government.', 'Quốc gia có một hệ thống chính quyền dân chủ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'accountability', 'Noun', '/ˌækaʊntəˈbɪlɪti/', 'trách nhiệm cá nhân', 'The company emphasizes the importance of accountability in the workplace.', 'Công ty nhấn mạnh tầm quan trọng của trách nhiệm cá nhân trong môi trường làm việc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'adversity', 'Noun', '/ˌædvərˈsɪti/', 'khó khăn', 'She faced many adversities in her life, but she never gave up.', 'Cô phải đối mặt với nhiều khó khăn trong cuộc sống, nhưng cô không bao giờ bỏ cuộc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'altruism', 'Noun', '/ˈæltruɪzəm/', 'tình yêu thương vô tư', 'Her altruism inspired many people to volunteer at the local charity.', 'Tình yêu thương vô tư của cô đã khích lệ nhiều người tham gia tình nguyện tại tổ chức từ thiện địa phương.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'aptitude', 'Noun', '/ˈæptɪtjuːd/', 'kỹ năng', 'She has an aptitude for mathematics and is planning to study it in college.', 'Cô có thiên hướng về toán học và đang lên kế hoạch học chuyên ngành này tại đại học.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'authenticity', 'Noun', '/ˌɔːθɛnˈtɪsɪti/', 'tính chân chính', 'The artist''s authenticity shines through in her artwork.', 'Tính chân chính của nghệ sĩ được thể hiện qua tác phẩm nghệ thuật của cô.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'candor', 'Noun', '/ˈkændər/', 'tính trung thực', 'He is known for his candor in business negotiations.', 'Anh ấy được biết đến với tính trung thực trong các cuộc đàm phán kinh doanh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'compassion', 'Noun', '/kəmˈpæʃən/', 'tình thương', 'The doctor showed compassion to the patient who was feeling sad.', 'Bác sĩ thể hiện tình thương với bệnh nhân đang cảm thấy buồn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'conscientious', 'Adjective', '/kɒnˈʃɛntʃəs/', 'trách nhiệm', 'She is a conscientious employee who always meets her deadlines.', 'Cô là một nhân viên trách nhiệm luôn hoàn thành đúng hạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'corporate', 'Adjective', '/ˈkɔːrpərɪt/', 'công ty', 'The corporate office is located in the city center.', 'Trụ sở công ty nằm ở trung tâm thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'credibility', 'Noun', '/krɪdɪˈbɪlɪti/', 'tính tin cậy', 'The scientist''s credibility was questioned after the scandal.', 'Tính tin cậy của nhà khoa học bị đặt câu hỏi sau scandal.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'discipline', 'Noun', '/dɪsˈɪplɪn/', 'trật tự', 'She has a great deal of discipline in her daily routine.', 'Cô có một lượng lớn kỷ luật trong lịch trình hàng ngày của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'efficiency', 'Noun', '/ɪˈfɪʃənsi/', 'hiệu suất', 'The new system improved efficiency in the production process.', 'Hệ thống mới đã cải thiện hiệu suất trong quá trình sản xuất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'empathy', 'Noun', '/ɛmˈpæθi/', 'tình đồng cảm', 'She showed empathy towards the victim of the accident.', 'Cô thể hiện tình đồng cảm với nạn nhân của tai nạn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'ethics', 'Noun', '/ˈiːθɪks/', 'tư tưởng đạo đức', 'The company has a strong code of ethics that guides its employees.', 'Công ty có một mã đạo đức mạnh mẽ dẫn dắt nhân viên của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'excellence', 'Noun', '/ɛksˈsɛləns/', 'tính ưu việt', 'The restaurant is known for its excellence in service.', 'Quán ăn được biết đến với tính ưu việt trong dịch vụ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'fairness', 'Noun', '/ˈfɛərnəs/', 'tính công bằng', 'The judge ensured fairness in the trial.', 'Hội đồng xét xử đảm bảo tính công bằng trong phiên tòa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'honesty', 'Noun', '/ˈɒnɪsɪti/', 'tính trung thực', 'He is known for his honesty in business dealings.', 'Anh ấy được biết đến với tính trung thực trong các giao dịch kinh doanh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'integrity', 'Noun', '/ɪnˈtɛɡrɪti/', 'tính toàn vẹn', 'The politician''s integrity was questioned after the scandal.', 'Tính toàn vẹn của chính trị gia bị đặt câu hỏi sau scandal.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 6, 'loyalty', 'Noun', '/ˈloʊəlti/', 'tình trung thành', 'She showed loyalty to her friends during difficult times.', 'Cô thể hiện tình trung thành với bạn bè trong những thời điểm khó khăn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'sustainability', 'Noun', '/sʌstənˈæbɪlɪti/', 'sự bền vững', 'The company''s goal is to achieve sustainability in its operations.', 'Mục tiêu của công ty là đạt được sự bền vững trong hoạt động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'ecosystem', 'Noun', '/ˈiːkəʊsɪstəm/', 'hệ sinh thái', 'The forest is a vital part of the local ecosystem.', 'Rừng là một phần quan trọng của hệ sinh thái địa phương.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'carbon footprint', 'Noun', '/ˈkɑːrbən ˈfʊtprɪnt/', 'đường cong carbon', 'Reducing our carbon footprint is essential for a sustainable future.', 'Giảm thiểu đường cong carbon của chúng ta là cần thiết cho một tương lai bền vững.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'renewable', 'Adjective', '/rɪˈnuːəbl/', 'tái tạo được', 'Renewable energy sources are becoming increasingly popular.', 'Nguồn năng lượng tái tạo đang trở nên phổ biến hơn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'conservation', 'Noun', '/kənˈsɜːrvəʃən/', 'bảo tồn', 'Conservation efforts are crucial for protecting endangered species.', 'Nỗ lực bảo tồn là cần thiết để bảo vệ các loài đang bị đe dọa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'recycle', 'Verb', '/rɪˈsaɪkəl/', 'chuyển đổi vật liệu', 'Recycling is an important part of reducing waste.', 'Chuyển đổi vật liệu là một phần quan trọng trong việc giảm thiểu rác thải.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'sustainable development', 'Noun', '/sʌstənəˈbleɪ dɪˈvəlpəmənt/', 'phát triển bền vững', 'Sustainable development is a key goal of the United Nations.', 'Phát triển bền vững là một mục tiêu quan trọng của Liên Hợp Quốc.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'climate change', 'Noun', '/ˈklaimət tʃeɪndʒ/', 'biến đổi khí hậu', 'Climate change is a major threat to global security.', 'Biến đổi khí hậu là một mối đe dọa lớn đối với an ninh toàn cầu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'biodiversity', 'Noun', '/baɪoʊˈdaɪvərˌsɪti/', 'sự đa dạng sinh học', 'Biodiversity is essential for maintaining healthy ecosystems.', 'Sự đa dạng sinh học là cần thiết để duy trì hệ sinh thái khỏe mạnh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'greenhouse gas', 'Noun', '/ˈɡriːnhaʊs ɡæs/', 'khí nhà kính', 'Greenhouse gases are released through human activities such as burning fossil fuels.', 'Khí nhà kính được giải phóng thông qua các hoạt động của con người như đốt nhiên liệu hóa thạch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'pollution', 'Noun', '/ˈpɒljʊʃən/', 'ô nhiễm', 'Pollution is a major problem in many parts of the world.', 'Ô nhiễm là một vấn đề lớn ở nhiều nơi trên thế giới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'resource', 'Noun', '/ˈrɪsərs/', 'nguồn tài nguyên', 'Water is a vital resource for human survival.', 'Nước là một nguồn tài nguyên quan trọng cho sự sống của con người.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'sustainable agriculture', 'Noun', '/sʌstənəˈbleɪ ˌægrɪˈkʌltʃər/', 'lương nông bền vững', 'Sustainable agriculture is a key aspect of reducing our carbon footprint.', 'Lương nông bền vững là một phần quan trọng trong việc giảm thiểu đường cong carbon của chúng ta.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'waste management', 'Noun', '/weɪst mænˈdʒmənt/', 'quản lý rác thải', 'Effective waste management is crucial for maintaining a clean environment.', 'Quản lý rác thải hiệu quả là cần thiết để duy trì môi trường sạch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'renewable energy', 'Noun', '/rɪˈnuːəbl ˈenədʒi/', 'năng lượng tái tạo', 'Renewable energy sources are becoming increasingly popular as a sustainable alternative to fossil fuels.', 'Nguồn năng lượng tái tạo đang trở nên phổ biến hơn như một lựa chọn bền vững thay thế cho nhiên liệu hóa thạch.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'climate resilience', 'Noun', '/ˈklaimət rɪˈzɪəns/', 'khả năng chống chịu biến đổi khí hậu', 'Climate resilience is essential for building a sustainable future.', 'Khả năng chống chịu biến đổi khí hậu là cần thiết để xây dựng một tương lai bền vững.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 7, 'ecological footprint', 'Noun', '/ˌiːkəˈlɒdʒɪkəl ˈfʊtprɪnt/', 'đường cong sinh thái', 'Reducing our ecological footprint is crucial for a sustainable future.', 'Giảm thiểu đường cong sinh thái của chúng ta là cần thiết cho một tương lai bền vững.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'asteroid', 'Noun', '/ˈæstərɔɪd/', 'hạt sao', 'The asteroid is expected to pass close to Earth.', 'Hạt sao này dự kiến sẽ đi qua gần Trái Đất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'blackhole', 'Noun', '/ˈblækhaʊl/', 'hố đen', 'The black hole is warping the space-time around it.', 'Hố đen đang làm cong không gian và thời gian xung quanh nó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'comet', 'Noun', '/ˈkɒmɪt/', 'sao chổi', 'The comet is visible in the night sky.', 'Sao chổi này có thể nhìn thấy trong bầu trời đêm.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'cosmic', 'Adjective', '/ˈkɒzmɪk/', 'về vũ trụ', 'The cosmic microwave background radiation is a key area of research.', 'Nhiễu xạ microwave vũ trụ là một lĩnh vực nghiên cứu quan trọng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'galaxy', 'Noun', '/ˈɡæləksi/', 'vũ trụ', 'The Milky Way is a galaxy that contains our solar system.', 'Chòm sao Ngân Hà là một thiên hà chứa hệ Mặt Trời của chúng ta.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'gravitational', 'Adjective', '/ˌɡrævɪˈteɪʃənəl/', 'về lực hấp dẫn', 'The gravitational pull of the Earth keeps us on the ground.', 'Lực hấp dẫn của Trái Đất giữ chúng ta trên mặt đất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'helium', 'Noun', '/ˈhiːliəm/', 'helium', 'Helium is used in balloons and airships.', 'Helium được sử dụng trong bóng bay và tàu bay.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'meteor', 'Noun', '/mɪˈtɔːrər/', 'tiểu thiên thạch', 'The meteor was seen streaking across the sky.', 'Tiểu thiên thạch này được nhìn thấy khi nó đi qua bầu trời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'nebula', 'Noun', '/nɪˈbuːlə/', 'vụ nổ sao', 'The nebula is a vast, star-forming region.', 'Vụ nổ sao này là một vùng rộng lớn hình thành sao.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'nucleus', 'Noun', '/ˈnjuːkliːəs/', 'lõi', 'The nucleus of the atom is surrounded by electrons.', 'Lõi của nguyên tử được bao quanh bởi electron.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'orbit', 'Verb', '/ˈɔrbɪt/', 'bay quanh', 'The Earth orbits the Sun.', 'Trái Đất bay quanh Mặt Trời.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'parallax', 'Noun', '/ˈpærəlæks/', 'hiệu ứng parallax', 'The parallax of the star is used to measure its distance.', 'Hiệu ứng parallax của sao được sử dụng để đo khoảng cách của nó.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'planet', 'Noun', '/ˈpleɪnt/', 'trái đất', 'The planet is a terrestrial body.', 'Trái đất này là một thiên thể đất liền.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'relativity', 'Noun', '/ˌrɛləˈtɪvɪti/', 'đại số tương đối', 'The theory of relativity is a fundamental concept in physics.', 'Đại số tương đối là một khái niệm cơ bản trong vật lý.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'satellite', 'Noun', '/ˈsætɪlɪt/', 'trạm quan sát', 'The satellite is used for communication and navigation.', 'Trạm quan sát này được sử dụng cho giao tiếp và định vị.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'spacecraft', 'Noun', '/ˈspeɪskræft/', 'khai thác vũ trụ', 'The spacecraft is equipped with advanced technology.', 'Khai thác vũ trụ này được trang bị công nghệ tiên tiến.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'star', 'Noun', '/stɑːr/', 'sao', 'The star is a celestial body.', 'Sao này là một thiên thể.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'telescope', 'Noun', '/tɛlɪˈskoop/', 'điện tử', 'The telescope is used to study the universe.', 'Điện tử này được sử dụng để nghiên cứu vũ trụ.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 8, 'universe', 'Noun', '/juːˈnɪvərs/', 'vũ trụ', 'The universe is vast and complex.', 'Vũ trụ này rộng lớn và phức tạp.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'macroeconomic', 'Adjective', '/ˌmækroʊˈɛkənɪk/', 'vĩ mô', 'The government implemented macroeconomic policies to stimulate growth.', 'Chính phủ đã thực hiện các chính sách vĩ mô để kích thích tăng trưởng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'inflation', 'Noun', '/ɪnˈflæʃən/', 'lạm phát', 'The central bank is trying to control inflation by raising interest rates.', 'Ngân hàng trung ương đang cố gắng kiểm soát lạm phát bằng cách tăng lãi suất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'deflation', 'Noun', '/dɪˈflæʃən/', 'thâm hụt', 'The country is experiencing deflation due to a decline in demand.', 'Nước này đang trải qua thâm hụt do giảm nhu cầu.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'fiscal', 'Adjective', '/ˈfɪskəl/', 'hạch toán', 'The fiscal policy is designed to stimulate economic growth.', 'Chính sách hạch toán được thiết kế để kích thích tăng trưởng kinh tế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'monetary', 'Adjective', '/məˈnɛtəri/', 'tiền tệ', 'The central bank uses monetary policy to control inflation.', 'Ngân hàng trung ương sử dụng chính sách tiền tệ để kiểm soát lạm phát.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'stimulate', 'Verb', '/stɪmʊˈleɪt/', 'kích thích', 'The government is trying to stimulate economic growth by investing in infrastructure.', 'Chính phủ đang cố gắng kích thích tăng trưởng kinh tế bằng cách đầu tư vào cơ sở hạ tầng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'sustainable', 'Adjective', '/sʌsˈteɪnəbəl/', 'sử dụng bền vững', 'The company is committed to sustainable practices in its operations.', 'Công ty cam kết thực hiện các thực hành bền vững trong hoạt động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'equilibrium', 'Noun', '/ˌɛkwɪˈlɪbrɪəm/', 'tương đối ổn định', 'The economy is in a state of equilibrium, with low unemployment and stable prices.', 'Kinh tế đang ở một trạng thái tương đối ổn định, với tỷ lệ thất nghiệp thấp và giá cả ổn định.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'aggregate', 'Noun', '/əˈɡriːɡeɪt/', 'tổng hợp', 'The aggregate demand for goods and services is increasing.', 'Tổng cầu hàng hóa và dịch vụ đang tăng lên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'macro', 'Adjective', '/ˈmækroʊ/', 'vĩ mô', 'The macroeconomic indicators are showing a positive trend.', 'Các chỉ số vĩ mô đang cho thấy một xu hướng tích cực.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'aggregate', 'Verb', '/əˈɡriːɡeɪt/', 'tổng hợp', 'The company is aggregating data from various sources to improve its analysis.', 'Công ty đang tổng hợp dữ liệu từ các nguồn khác nhau để cải thiện phân tích của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'fiscal', 'Noun', '/ˈfɪskəl/', 'hạch toán', 'The fiscal policy is designed to stimulate economic growth.', 'Chính sách hạch toán được thiết kế để kích thích tăng trưởng kinh tế.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'monetary', 'Noun', '/məˈnɛtəri/', 'tiền tệ', 'The central bank uses monetary policy to control inflation.', 'Ngân hàng trung ương sử dụng chính sách tiền tệ để kiểm soát lạm phát.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'stimulate', 'Noun', '/stɪmʊˈleɪt/', 'kích thích', 'The government is trying to stimulate economic growth by investing in infrastructure.', 'Chính phủ đang cố gắng kích thích tăng trưởng kinh tế bằng cách đầu tư vào cơ sở hạ tầng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'sustainable', 'Noun', '/sʌsˈteɪnəbəl/', 'sử dụng bền vững', 'The company is committed to sustainable practices in its operations.', 'Công ty cam kết thực hiện các thực hành bền vững trong hoạt động của mình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'equilibrium', 'Verb', '/ˌɛkwɪˈlɪbrɪəm/', 'tương đối ổn định', 'The government is trying to bring the economy into equilibrium by implementing fiscal policies.', 'Chính phủ đang cố gắng đưa kinh tế vào trạng thái tương đối ổn định bằng cách thực hiện các chính sách hạch toán.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'aggregate', 'Adjective', '/əˈɡriːɡeɪt/', 'tổng hợp', 'The aggregate demand for goods and services is increasing.', 'Tổng cầu hàng hóa và dịch vụ đang tăng lên.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 9, 'macro', 'Noun', '/ˈmækroʊ/', 'vĩ mô', 'The macroeconomic indicators are showing a positive trend.', 'Các chỉ số vĩ mô đang cho thấy một xu hướng tích cực.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'subculture', 'Noun', '/ˈsʌbkʌltʃər/', 'tâm lý xã hội của một nhóm nhỏ', 'The subculture of the 1960s was characterized by its love of music and fashion.', 'Tâm lý xã hội của thập niên 1960 được đặc trưng bởi tình yêu âm nhạc và thời trang.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'hipster', 'Noun', '/ˈhɪpsər/', 'người theo đuổi phong cách văn hóa độc lập', 'The hipster cafe was filled with people sipping artisanal coffee.', 'Cà phê hipster đầy người đang uống cà phê thủ công.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'mainstream', 'Adjective', '/ˈmeɪnˌstriːm/', 'phổ biến, được nhiều người biết đến', 'The new movie was a mainstream success, appealing to a broad audience.', 'Phim mới này là một thành công lớn, thu hút được khán giả rộng lớn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'alternative', 'Adjective', '/ˌæltəˈnætɪv/', 'phương án thay thế', 'The alternative music scene was thriving in the city.', 'Scène âm nhạc thay thế đang thịnh hành ở thành phố.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'consume', 'Verb', '/kənˈsuːm/', 'sử dụng, tiêu thụ', 'People consume a lot of energy drinks to stay awake during exams.', 'Người ta tiêu thụ nhiều đồ uống năng lượng để thức tỉnh trong kỳ thi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'sustainability', 'Noun', '/ˌsʌstənˈæbɪlɪti/', 'sự bền vững', 'The company''s goal is to achieve sustainability in its production process.', 'Mục tiêu của công ty là đạt được sự bền vững trong quy trình sản xuất.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'diversity', 'Noun', '/dɪˈvɜːr.sɪti/', 'sự đa dạng', 'The city celebrates its diversity with a multicultural festival.', 'Thành phố tôn vinh sự đa dạng của mình bằng một lễ hội đa văn hóa.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'influence', 'Noun', '/ɪnˈflʊəns/', 'sự ảnh hưởng', 'The social media influencer has a significant influence on her followers.', 'Người ảnh hưởng trên mạng xã hội có ảnh hưởng đáng kể đối với người theo dõi.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'authentic', 'Adjective', '/ɔːˈθɛntɪk/', 'chính xác, chân thực', 'The authentic Italian restaurant served delicious pasta dishes.', 'Quán ăn Ý chân thực phục vụ các món mì ngon.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'globalization', 'Noun', '/ˌɡloʊbəlˈaɪˌzeɪʃən/', 'sự toàn cầu hóa', 'The company''s goal is to achieve globalization in its business operations.', 'Mục tiêu của công ty là đạt được sự toàn cầu hóa trong hoạt động kinh doanh.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'cosmopolitan', 'Adjective', '/kɒzməˈpɒltən/', 'phong cách văn hóa đa dạng, hiện đại', 'The cosmopolitan city has a diverse population with many different cultures.', 'Thành phố đa dạng có dân số đa dạng với nhiều nền văn hóa khác nhau.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'suburban', 'Adjective', '/ˈsʌbərbən/', 'phong cách sống ở ngoại ô', 'The suburban area has a quiet and peaceful atmosphere.', 'Khu vực ngoại ô có không khí yên tĩnh và yên bình.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'urbanization', 'Noun', '/ˌɜːrbənaɪˈzeɪʃən/', 'sự đô thị hóa', 'The city is experiencing rapid urbanization, with many people moving from rural areas.', 'Thành phố đang trải qua quá trình đô thị hóa nhanh chóng, với nhiều người di chuyển từ các khu vực nông thôn.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'societal', 'Adjective', '/səˈsaɪɪəl/', 'liên quan đến xã hội', 'The societal norms of the country are changing rapidly.', 'Các chuẩn mực xã hội của đất nước đang thay đổi nhanh chóng.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'cultural', 'Adjective', '/ˈkʌltʃərəl/', 'liên quan đến văn hóa', 'The cultural festival was a huge success, attracting visitors from all over the world.', 'Lễ hội văn hóa là một thành công lớn, thu hút khách du lịch từ khắp thế giới.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'identity', 'Noun', '/aɪdənˈtaɪ/', 'tính cách, bản dạng', 'The artist''s identity was revealed after a long period of speculation.', 'Tính cách của nghệ sĩ được tiết lộ sau một thời gian dài suy đoán.');
INSERT INTO vocabulary_words (cefr_level, module_index, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES ('C1', 10, 'diversify', 'Verb', '/dɪˈvɜːr.sɪfaɪ/', 'tạo sự đa dạng', 'The company is trying to diversify its product line to appeal to a wider audience.', 'Công ty đang cố gắng đa dạng hóa dòng sản phẩm để thu hút được khán giả rộng lớn hơn.');
